-- Application tables stay outside the exposed Data API schema.
create schema if not exists fauxlore;
revoke all on schema fauxlore from public, anon, authenticated;
alter default privileges in schema fauxlore revoke execute on functions from public;

create table if not exists fauxlore.provinces (
  id integer primary key check (id > 0 and id < 16777216),
  kind text not null check (kind in ('land','sea','lake')),
  name text not null, center jsonb not null, bbox jsonb not null,
  area bigint not null check (area > 0), seed_area bigint not null,
  population bigint not null default 0 check (population >= 0),
  development integer check (development between 0 and 1000000),
  province_type text not null default 'Регион'
    check (province_type in ('Столичная','Городская','Регион','Территориальная')),
  belonging text not null default 'Отсутствует'
    check (belonging in ('Корона','Знать','Духовенство','Горожане','Крестьяне','Отсутствует')),
  trade_status text not null default 'Отсутствует'
    check (trade_status in ('Отсутствует','Устье реки','Природный порт','Центр торговли I','Центр торговли II','Центр торговли III')),
  control smallint not null default 100 check (control between 0 and 100),
  occupation text check (occupation is null or length(btrim(occupation)) between 1 and 100),
  terrain_type text check (terrain_type in ('forest','marsh')),
  has_capital_marker boolean not null default false,
  has_city_marker boolean not null default false,
  taxes numeric, production jsonb, tension numeric
);
create table if not exists fauxlore.map_categories (
  layer text not null check (layer in ('states','races','religions','resources','trade','climate')),
  id integer not null, name text not null,
  color text not null check (color ~ '^#[0-9a-fA-F]{6}$'), primary key (layer,id)
);
create unique index if not exists category_name_idx on fauxlore.map_categories(layer,lower(name));
create or replace function fauxlore.clear_deleted_state_occupation() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
  if old.layer='states' then
    update fauxlore.provinces set occupation=null where lower(occupation)=lower(old.name);
  end if;
  return old;
end $$;

drop trigger if exists clear_deleted_state_occupation on fauxlore.map_categories;
create trigger clear_deleted_state_occupation before delete on fauxlore.map_categories
for each row execute function fauxlore.clear_deleted_state_occupation();
create table if not exists fauxlore.province_values (
  province_id integer not null references fauxlore.provinces on delete cascade,
  layer text not null, category_id integer not null, primary key (province_id,layer),
  foreign key (layer,category_id) references fauxlore.map_categories
);
create index if not exists province_category_idx on fauxlore.province_values(layer,category_id,province_id);
create table if not exists fauxlore.map_markers (
  id bigint generated by default as identity primary key,
  province_id integer not null references fauxlore.provinces,
  x double precision not null, y double precision not null,
  type text not null check (type in ('capital','city','fortress','port')),
  name text not null check (length(name) between 1 and 120),
  state_layer text not null default 'states' check (state_layer='states'), state_id integer,
  description text check (description is null), created_at timestamptz not null default now(),
  foreign key (state_layer,state_id) references fauxlore.map_categories
);
create index if not exists marker_province_idx on fauxlore.map_markers(province_id);
create index if not exists marker_state_idx on fauxlore.map_markers(state_layer,state_id);
create or replace function fauxlore.sync_province_type_from_markers() returns trigger
language plpgsql security invoker set search_path='' as $$
declare target_id integer; target_ids integer[]; has_capital boolean; has_city boolean;
begin
  if tg_op='INSERT' then target_ids:=array[new.province_id];
  elsif tg_op='DELETE' then target_ids:=array[old.province_id];
  else target_ids:=array[old.province_id,new.province_id]; end if;
  for target_id in select distinct unnest(target_ids) loop
    select exists(select 1 from fauxlore.map_markers where province_id=target_id and type='capital'),
      exists(select 1 from fauxlore.map_markers where province_id=target_id and type='city')
      into has_capital,has_city;
    update fauxlore.provinces set has_capital_marker=has_capital,has_city_marker=has_city,
      province_type=case when has_capital then 'Столичная' when has_city then 'Городская'
        when province_type='Территориальная' then 'Территориальная' else 'Регион' end
      where id=target_id;
  end loop;
  return null;
end $$;
drop trigger if exists sync_province_type_from_markers on fauxlore.map_markers;
create trigger sync_province_type_from_markers
after insert or update or delete on fauxlore.map_markers
for each row execute function fauxlore.sync_province_type_from_markers();
create table if not exists fauxlore.accounts (
  id bigint generated by default as identity primary key,
  auth_user_id uuid unique references auth.users(id) on delete set null,
  email text not null unique, nickname text not null,
  role text not null default 'player' check (role in ('player','admin')),
  created_at timestamptz not null default now(), reputation integer not null default 0,
  avatar_base64 text, avatar_type text, is_test_profile boolean not null default false,
  google_sub text unique
);
create unique index if not exists account_email_idx on fauxlore.accounts(lower(email));
create table if not exists fauxlore.account_states (
  account_id bigint not null references fauxlore.accounts on delete cascade,
  layer text not null default 'states' check (layer='states'), state_id integer not null,
  primary key (account_id,state_id), foreign key (layer,state_id) references fauxlore.map_categories
);
create index if not exists account_state_idx on fauxlore.account_states(layer,state_id);
create table if not exists fauxlore.state_profiles (
  state_layer text not null default 'states' check (state_layer='states'),
  state_id integer primary key,
  is_npc boolean not null default true,
  principles jsonb not null,
  government_name text not null,
  race_layer text not null default 'races' check (race_layer='races'),
  official_race_id integer not null,
  religion_layer text not null default 'religions' check (religion_layer='religions'),
  official_religion_id integer not null,
  corruption numeric(5,4) not null default 0.2 check (corruption between 0.02 and 0.9),
  crime numeric(5,4) not null default 0.2 check (crime between 0.02 and 1.0),
  emblem_base64 text, emblem_type text,
  created_by bigint references fauxlore.accounts(id),
  created_at timestamptz not null default now(),
  foreign key (state_layer,state_id) references fauxlore.map_categories(layer,id),
  foreign key (race_layer,official_race_id) references fauxlore.map_categories(layer,id),
  foreign key (religion_layer,official_religion_id) references fauxlore.map_categories(layer,id)
);
alter table fauxlore.state_profiles enable row level security;
revoke all on fauxlore.state_profiles from public,anon,authenticated;
create table if not exists fauxlore.user_preferences (
  account_id bigint primary key references fauxlore.accounts on delete cascade,
  settings jsonb not null default '{}'
);
create table if not exists fauxlore._settings (key text primary key, value_json jsonb not null);
create table if not exists fauxlore.economy_parameters (
  singleton boolean primary key default true check (singleton),
  config jsonb not null,
  updated_at timestamptz not null default now()
);
alter table fauxlore.economy_parameters enable row level security;
revoke all on fauxlore.economy_parameters from public,anon,authenticated;
create table if not exists fauxlore.economy_parameter_history (
  id bigint generated by default as identity primary key,
  account_id bigint not null references fauxlore.accounts on delete restrict,
  changed_at timestamptz not null default now(), before_config jsonb not null, after_config jsonb not null
);
create index if not exists economy_parameter_history_account_changed_idx on fauxlore.economy_parameter_history(account_id,changed_at desc);
alter table fauxlore.economy_parameter_history enable row level security;
revoke all on fauxlore.economy_parameter_history from public,anon,authenticated;
