create or replace function fauxlore.economy_config_payload() returns jsonb
language sql stable security definer set search_path='' as $$
  select config from fauxlore.economy_parameters where singleton=true
$$;
revoke all on function fauxlore.economy_config_payload() from public,anon,authenticated;
grant execute on function fauxlore.economy_config_payload() to anon,authenticated;
create table if not exists fauxlore.archived_markers (id bigint primary key, payload jsonb not null);
create table if not exists fauxlore.operations (
  account_id bigint not null references fauxlore.accounts on delete cascade,
  request_id uuid not null, fingerprint text not null, result jsonb not null,
  created_at timestamptz not null default now(), primary key (account_id,request_id)
);
create table if not exists fauxlore.game_calendar (
  singleton boolean primary key default true check(singleton),
  year integer not null check(year>0), turn integer not null check(turn>0),
  updated_at timestamptz not null default now()
);
insert into fauxlore.game_calendar(singleton,year,turn) values(true,1452,1) on conflict(singleton) do nothing;
alter table fauxlore.game_calendar enable row level security;
revoke all on fauxlore.game_calendar from public,anon,authenticated;
create table if not exists fauxlore.turn_economy_reports (
  year integer not null, turn integer not null,
  report jsonb not null check(jsonb_typeof(report)='array'),
  created_by bigint not null references fauxlore.accounts(id), created_at timestamptz not null default now(),
  primary key(year,turn)
