alter table fauxlore.turn_economy_reports enable row level security;
revoke all on fauxlore.turn_economy_reports from public,anon,authenticated;
create table if not exists fauxlore.import_batches (
  id text primary key, sha256 text not null, created_at timestamptz not null default now()
);
do $$ declare item record; begin
  for item in select tablename from pg_tables where schemaname='fauxlore' loop
    execute format('alter table fauxlore.%I enable row level security',item.tablename);
  end loop;
end $$;
revoke all on all tables in schema fauxlore from public, anon, authenticated;
revoke all on all sequences in schema fauxlore from public, anon, authenticated;

-- These helpers run only inside the checked dispatcher. No caller-supplied role
-- or account id is trusted. Legacy ids and roles survive the migration.
create or replace function fauxlore.current_account() returns fauxlore.accounts
language plpgsql security invoker set search_path='' as $$
declare a fauxlore.accounts; identity jsonb; email_address text; uid uuid:=auth.uid();
begin
  if uid is null then raise sqlstate '28000' using message='Войдите через Google'; end if;
  select identity_data into identity from auth.identities where user_id=uid and provider='google' limit 1;
  select lower(email) into email_address from auth.users where id=uid and email_confirmed_at is not null;
  if identity is null or email_address is null or identity->>'email_verified' is distinct from 'true'
      or coalesce(identity->>'sub','')='' then
    raise sqlstate '42501' using message='Нужен подтверждённый Google-аккаунт';
  end if;
  select * into a from fauxlore.accounts where auth_user_id=uid;
  if found then return a; end if;
  -- Serialize only linking/creating this identity, never all map writes.
  perform pg_advisory_xact_lock(hashtextextended(email_address,0));
  select * into a from fauxlore.accounts where auth_user_id=uid;
  if found then return a; end if;
  select * into a from fauxlore.accounts where google_sub=identity->>'sub' for update;
  if not found then
    select * into a from fauxlore.accounts where lower(email)=email_address and not is_test_profile for update;
    if found and (a.google_sub is not null or
        (email_address not like '%@gmail.com' and coalesce(identity->>'hd','')='')) then
      raise sqlstate '42501' using message='Для привязки старого аккаунта обратитесь к администратору';
    end if;
  end if;
  if a.id is null then
    insert into fauxlore.accounts(auth_user_id,email,nickname,google_sub)
      values(uid,email_address,left(coalesce(nullif(identity->>'name',''),split_part(email_address,'@',1)),40),identity->>'sub') returning * into a;
  else
    if a.auth_user_id is not null and a.auth_user_id<>uid then raise sqlstate '42501' using message='Аккаунт уже привязан'; end if;
    update fauxlore.accounts set auth_user_id=uid,google_sub=identity->>'sub' where id=a.id returning * into a;
  end if;
  return a;
end $$;

create or replace function fauxlore.profile(a fauxlore.accounts) returns jsonb
language sql stable security invoker set search_path='' as $$
select jsonb_build_object('id',a.id,'email',a.email,'nickname',a.nickname,'role',a.role,
  'reputation',a.reputation,'avatar_type',a.avatar_type,
  'avatar_url',case when a.avatar_base64 is null then null else 'data:'||a.avatar_type||';base64,'||a.avatar_base64 end,
  'state_ids',coalesce((select jsonb_agg(state_id order by state_id) from fauxlore.account_states where account_id=a.id),'[]'))
$$;

create or replace function fauxlore.province_payload(p fauxlore.provinces) returns jsonb
language sql stable security invoker set search_path='' as $$
select to_jsonb(p)||jsonb_build_object('layers',coalesce((select jsonb_object_agg(v.layer,
  jsonb_build_object('id',c.id,'name',c.name,'color',c.color)||case when v.layer='states' then
    jsonb_build_object('crime',coalesce((select sp.crime from fauxlore.state_profiles sp where sp.state_id=c.id),0.2))
    else '{}'::jsonb end)
  from fauxlore.province_values v join fauxlore.map_categories c on c.layer=v.layer and c.id=v.category_id
  where v.province_id=p.id),'{}'),
  'occupation_color',(select c.color from fauxlore.map_categories c
    where c.layer='states' and lower(c.name)=lower(p.occupation) limit 1))
$$;

-- Road storage and validation. Loaded after the base tables in schema.sql.
create table if not exists fauxlore.map_roads (
  id bigint generated by default as identity primary key,
  type text not null check(type in ('trail','highway','imperial')),
  anchors jsonb not null check(jsonb_typeof(anchors)='array'),
  segments jsonb not null check(jsonb_typeof(segments)='array'),
  created_by bigint not null references fauxlore.accounts,
  created_at timestamptz not null default now()
);
alter table fauxlore.map_roads enable row level security;
revoke all on fauxlore.map_roads from public,anon,authenticated;
revoke all on sequence fauxlore.map_roads_id_seq from public,anon,authenticated;

create or replace function fauxlore.create_road(body jsonb, account_id bigint) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare anchor jsonb; point jsonb; segment jsonb; anchors jsonb:=body->'anchors'; segments jsonb:=body->'segments';
  p fauxlore.provinces; q fauxlore.provinces; m fauxlore.map_markers; r fauxlore.map_roads;
  i integer; n integer; x numeric; y numeric; bounds jsonb;
begin
  if body-array['type','anchors','segments']<>'{}' or body->>'type' is null or body->>'type' not in ('trail','highway','imperial')
    or jsonb_typeof(anchors) is distinct from 'array' or jsonb_typeof(segments) is distinct from 'array' then
    raise sqlstate '22023' using message='Некорректная дорога'; end if;
  n:=jsonb_array_length(anchors);
  if n<2 or n>64 or jsonb_array_length(segments)<>n-1 then raise sqlstate '22023' using message='Нужно от 2 до 64 точек дороги'; end if;
  select value_json into bounds from fauxlore._settings where key='region';
  for i in 0..n-1 loop
    anchor:=anchors->i;
    if jsonb_typeof(anchor) is distinct from 'object' or anchor-array['kind','province_id','marker_id','x','y']<>'{}'
      or jsonb_typeof(anchor->'province_id') is distinct from 'number'
      or jsonb_typeof(anchor->'x') is distinct from 'number' or jsonb_typeof(anchor->'y') is distinct from 'number' then
      raise sqlstate '22023' using message='Некорректная точка привязки'; end if;
    select * into p from fauxlore.provinces where id=(anchor->>'province_id')::integer and kind='land';
    if not found then raise sqlstate '22023' using message='Дороги можно прокладывать только по суше'; end if;
    x:=(anchor->>'x')::numeric;y:=(anchor->>'y')::numeric;
    if x<(bounds->>0)::numeric or y<(bounds->>1)::numeric or x>=(bounds->>2)::numeric or y>=(bounds->>3)::numeric then
      raise sqlstate '22023' using message='Точка вне игровой области'; end if;
    if anchor->>'kind'='province' then
      if anchor?'marker_id' or abs(x-(p.center->>0)::numeric)>.001 or abs(y-(p.center->>1)::numeric)>.001 then
        raise sqlstate '22023' using message='Укажите центр провинции'; end if;
    elsif anchor->>'kind'='marker' then
      if jsonb_typeof(anchor->'marker_id') is distinct from 'number' then raise sqlstate '22023' using message='Не указан маркер'; end if;
      select * into m from fauxlore.map_markers where id=(anchor->>'marker_id')::bigint and province_id=p.id;
      if not found or abs(x-m.x)>.001 or abs(y-m.y)>.001 then raise sqlstate '22023' using message='Маркер изменён или удалён'; end if;
    else raise sqlstate '22023' using message='Неизвестный вид точки привязки'; end if;
  end loop;
  for i in 0..n-2 loop
    segment:=segments->i;
    if jsonb_typeof(segment) is distinct from 'array' then raise sqlstate '22023' using message='Некорректный участок'; end if;
    if jsonb_array_length(segment)<2 or jsonb_array_length(segment)>8192 then raise sqlstate '22023' using message='Некорректная длина участка'; end if;
    select * into p from fauxlore.provinces where id=(anchors->i->>'province_id')::integer;
    select * into q from fauxlore.provinces where id=(anchors->(i+1)->>'province_id')::integer;
    for point in select * from jsonb_array_elements(segment) loop
      if jsonb_typeof(point) is distinct from 'array' then raise sqlstate '22023' using message='Некорректная геометрия'; end if;
      if jsonb_array_length(point)<>2 or jsonb_typeof(point->0) is distinct from 'number' or jsonb_typeof(point->1) is distinct from 'number' then
        raise sqlstate '22023' using message='Некорректные координаты дороги'; end if;
      x:=(point->>0)::numeric;y:=(point->>1)::numeric;
      if x<(bounds->>0)::numeric or y<(bounds->>1)::numeric or x>=(bounds->>2)::numeric or y>=(bounds->>3)::numeric
        or not ((x>=(p.bbox->>0)::numeric and x<(p.bbox->>2)::numeric and y>=(p.bbox->>1)::numeric and y<(p.bbox->>3)::numeric)
          or (x>=(q.bbox->>0)::numeric and x<(q.bbox->>2)::numeric and y>=(q.bbox->>1)::numeric and y<(q.bbox->>3)::numeric)) then
        raise sqlstate '22023' using message='Участок вне выбранных провинций'; end if;
    end loop;
    if abs((segment->0->>0)::numeric-(anchors->i->>'x')::numeric)>.001
      or abs((segment->0->>1)::numeric-(anchors->i->>'y')::numeric)>.001
      or abs((segment->-1->>0)::numeric-(anchors->(i+1)->>'x')::numeric)>.001
      or abs((segment->-1->>1)::numeric-(anchors->(i+1)->>'y')::numeric)>.001 then
      raise sqlstate '22023' using message='Участок не совпадает с точками привязки'; end if;
  end loop;
  insert into fauxlore.map_roads(type,anchors,segments,created_by) values(body->>'type',anchors,segments,account_id) returning * into r;
  return jsonb_build_object('id',r.id,'type',r.type,'anchors',r.anchors,'segments',r.segments);
end $$;
revoke all on function fauxlore.create_road(jsonb,bigint) from public,anon,authenticated;

create or replace function fauxlore.map_payload() returns jsonb
language sql stable security invoker set search_path='' as $$
with s as (select (select jsonb_object_agg(key,value_json) from fauxlore._settings)||jsonb_build_object('economy_config',fauxlore.economy_config_payload()) as data),
visible as (select p.* from fauxlore.provinces p cross join s where
  (p.bbox->>0)::numeric<(s.data->'region'->>2)::numeric and
  (p.bbox->>2)::numeric>(s.data->'region'->>0)::numeric and
  (p.bbox->>1)::numeric<(s.data->'region'->>3)::numeric and
  (p.bbox->>3)::numeric>(s.data->'region'->>1)::numeric),
layers as (select v.province_id,jsonb_object_agg(v.layer,jsonb_build_object('id',c.id,'name',c.name,'color',c.color)||
  case when v.layer='states' then jsonb_build_object('crime',coalesce((select sp.crime from fauxlore.state_profiles sp where sp.state_id=c.id),0.2))
    else '{}'::jsonb end) as data
  from fauxlore.province_values v join visible p on p.id=v.province_id
  join fauxlore.map_categories c on c.layer=v.layer and c.id=v.category_id group by v.province_id)
select s.data||jsonb_build_object('provinces',coalesce((select jsonb_agg(case when p.kind='sea' then
  to_jsonb(p)-array['province_type','population','development','taxes','production','warehouse','control','occupation','tension','has_capital_marker','has_city_marker']
  else to_jsonb(p)||jsonb_build_object('layers',coalesce(l.data,'{}'),'occupation_color',c.color) end order by p.id)
  from visible p left join layers l on l.province_id=p.id
  left join fauxlore.map_categories c on c.layer='states' and lower(c.name)=lower(p.occupation)),'[]'),
  'roads',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'type',r.type,'anchors',r.anchors,'segments',r.segments) order by r.id)
    from fauxlore.map_roads r where exists(select 1 from jsonb_array_elements(r.anchors) anchor join visible p on p.id=(anchor->>'province_id')::integer)),'[]'),
  'categories',coalesce((select jsonb_agg(to_jsonb(c)||case when c.layer='states' then
    jsonb_build_object('crime',coalesce(sp.crime,0.2)) else '{}'::jsonb end order by c.layer,c.id)
    from fauxlore.map_categories c left join fauxlore.state_profiles sp on sp.state_id=c.id and c.layer='states'),'[]'),
  'economy_config',coalesce((select config from fauxlore.economy_config where singleton=true),'{}'::jsonb),
  'economy_config',coalesce(fauxlore.economy_config_payload(),'{}'::jsonb),
  'markers',coalesce((select jsonb_agg(to_jsonb(m)||jsonb_build_object('state_name',c.name) order by m.id)
    from fauxlore.map_markers m join visible p on p.id=m.province_id
    left join fauxlore.map_categories c on c.layer=m.state_layer and c.id=m.state_id),'[]')) from s
$$;

create or replace function fauxlore.layer_for(field text) returns text
language sql immutable security invoker set search_path='' as $$
select case field when 'race' then 'races' when 'religion' then 'religions' when 'state' then 'states'
  when 'resource' then 'resources' when 'trade' then 'trade' when 'climate' then 'climate' end
$$;

create or replace function fauxlore.normalize(field text, value jsonb) returns jsonb
language plpgsql immutable security invoker set search_path='' as $$
declare t text:=nullif(btrim(value#>>'{}'),''); limit_length integer;
begin
  if field is null then raise sqlstate '22023' using message='Неизвестный параметр'; end if;
  if field in ('capital','city') then
    if jsonb_typeof(value) is distinct from 'boolean' then raise sqlstate '22023' using message='Укажите да или нет'; end if;
    return value;
  elsif field in ('population','development','control') then
    if value='null' and field='development' then return value; end if;
    if jsonb_typeof(value) is distinct from 'number' or t!~'^\d+$' then
      raise sqlstate '22023' using message=case when field='control' then 'Контроль должен быть целым числом от 0 до 100' else 'Укажите целое неотрицательное число' end; end if;
    if t::numeric>(case when field='population' then 2000000000 when field='control' then 100 else 1000000 end) or
      (field='control' and t::numeric<0) then
      raise sqlstate '22023' using message=case when field='control' then 'Контроль должен быть целым числом от 0 до 100' else 'Укажите целое неотрицательное число' end; end if;
    return value;
  elsif field='belonging' then
    if t is null or t not in ('Корона','Знать','Духовенство','Горожане','Крестьяне','Отсутствует') then raise sqlstate '22023' using message='Неизвестная принадлежность'; end if;
  elsif field='trade_status' then
    if t is null or t not in ('Отсутствует','Устье реки','Природный порт','Центр торговли I','Центр торговли II','Центр торговли III') then raise sqlstate '22023' using message='Неизвестный торговый статус'; end if;
  elsif field='province_type' then
    raise sqlstate '22023' using message='Тип провинции определяется автоматически';
  elsif field='terrain_type' then
    if value='null' then return value; end if;
    if t is null or t not in ('forest','marsh') then raise sqlstate '22023' using message='Неизвестный тип местности'; end if;
  elsif field='occupation' then
    if value='null' then return value; end if;
    if jsonb_typeof(value) is distinct from 'string' or t is null then raise sqlstate '22023' using message='Выберите государство-оккупанта или очистите поле'; end if;
  elsif field='name' then
    if t is null then raise sqlstate '22023' using message='Укажите название'; end if;
  elsif fauxlore.layer_for(field) is null then
    raise sqlstate '22023' using message='Неизвестный параметр';
  end if;
  if value<>'null' and jsonb_typeof(value)<>'string' then raise sqlstate '22023' using message='Некорректное текстовое значение'; end if;
  limit_length:=case when field='name' then 120 when field in ('state','occupation') then 100 else 80 end;
  if length(t)>limit_length then raise sqlstate '22023' using message='Слишком длинное значение'; end if;
  return coalesce(to_jsonb(t),'null');
end $$;

create or replace function fauxlore.category(layer_name text, category_name text, may_create boolean default false) returns integer
language plpgsql security invoker set search_path='' as $$
declare result integer; color_value text;
begin
  if category_name is null then return null; end if;
  select id into result from fauxlore.map_categories where layer=layer_name and lower(name)=lower(category_name);
  if result is null and may_create then
    -- Only creation of category identifiers is serialized, not province edits.
    perform pg_advisory_xact_lock(hashtextextended('category:'||layer_name,0));
    select id into result from fauxlore.map_categories where layer=layer_name and lower(name)=lower(category_name);
    if result is null then
      select coalesce(max(id),0)+1 into result from fauxlore.map_categories where layer=layer_name;
      color_value:='#'||substr(md5(category_name),1,6);
      insert into fauxlore.map_categories values(layer_name,result,category_name,color_value);
    end if;
  end if;
  if result is null then raise sqlstate '22023' using message='Неизвестное значение: '||category_name; end if;
  return result;
end $$;

create or replace function fauxlore.edit_province(province_id integer, changes jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare p fauxlore.provinces; item record; value jsonb; layer_name text; category_id integer; column_name text;
begin
  select * into p from fauxlore.provinces where id=province_id for update;
  if not found then raise sqlstate 'P0002' using message='Провинция не найдена'; end if;
  if p.kind<>'land' then raise sqlstate '22023' using message='Редактировать можно только сухопутные провинции'; end if;
  if jsonb_typeof(changes)<>'object' or changes='{}' then raise sqlstate '22023' using message='Нет изменений'; end if;
  for item in select * from jsonb_each(changes) order by key loop
    value:=fauxlore.normalize(item.key,item.value); layer_name:=fauxlore.layer_for(item.key);
    if layer_name is not null then
      category_id:=fauxlore.category(layer_name,value#>>'{}',layer_name='states');
      if category_id is null then
        delete from fauxlore.province_values v where v.province_id=p.id and v.layer=layer_name;
      else
        insert into fauxlore.province_values values(p.id,layer_name,category_id)
          on conflict on constraint province_values_pkey do update set category_id=excluded.category_id;
      end if;
    else
      if item.key='occupation' and value<>'null' then perform fauxlore.category('states',value#>>'{}',false); end if;
      column_name:=case item.key when 'capital' then 'has_capital_marker' when 'city' then 'has_city_marker' else item.key end;
      p:=jsonb_populate_record(p,jsonb_build_object(column_name,value));
    end if;
  end loop;
  if p.has_capital_marker then p.province_type:='Столичная';
  elsif p.has_city_marker then p.province_type:='Городская';
  elsif p.province_type<>'Территориальная' then p.province_type:='Регион'; end if;
  update fauxlore.provinces set name=p.name,province_type=p.province_type,population=p.population,
    development=p.development,belonging=p.belonging,trade_status=p.trade_status,
    control=p.control,occupation=p.occupation,terrain_type=p.terrain_type,
    has_capital_marker=p.has_capital_marker,has_city_marker=p.has_city_marker where id=p.id;
  return fauxlore.province_payload(p);
end $$;

create or replace function fauxlore.bulk_edit(body jsonb, apply_changes boolean) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare rule jsonb; rules jsonb:='[]'; counts jsonb:='[]'; changes jsonb; merged jsonb:='{}';
  expected jsonb; actual jsonb; p fauxlore.provinces; entry record; total integer:=0; conflicts integer:=0;
  conflict_ids jsonb:='[]'; i integer; count_i integer; bounds jsonb; payload jsonb;
begin
  if jsonb_typeof(body->'rules') is distinct from 'array' or jsonb_array_length(body->'rules') not between 1 and 50 then
    raise sqlstate '22023' using message='Нужно от 1 до 50 правил'; end if;
  for rule in select * from jsonb_array_elements(body->'rules') loop
    if rule->>'target_field'='name' then raise sqlstate '22023' using message='Массовое переименование отключено'; end if;
    rule:=rule||jsonb_build_object('condition_value',fauxlore.normalize(rule->>'condition_field',coalesce(rule->'condition_value','null')),
      'target_value',fauxlore.normalize(rule->>'target_field',coalesce(rule->'target_value','null')));
    if fauxlore.layer_for(rule->>'condition_field') is not null then
      perform fauxlore.category(fauxlore.layer_for(rule->>'condition_field'),rule->>'condition_value',false); end if;
    if fauxlore.layer_for(rule->>'target_field') is not null and rule->>'target_field'<>'state' then
      perform fauxlore.category(fauxlore.layer_for(rule->>'target_field'),rule->>'target_value',false); end if;
    if rule->>'condition_field'='occupation' and rule->'condition_value'<>'null'::jsonb then
      perform fauxlore.category('states',rule->>'condition_value',false); end if;
    if rule->>'target_field'='occupation' and rule->'target_value'<>'null'::jsonb then
      perform fauxlore.category('states',rule->>'target_value',false); end if;
    rules:=rules||jsonb_build_array(rule); counts:=counts||'0'::jsonb;
  end loop;
  select value_json into bounds from fauxlore._settings where key='region';
  for p in select * from fauxlore.provinces where kind='land'
    and (center->>0)::numeric>=(bounds->>0)::numeric and (center->>0)::numeric<(bounds->>2)::numeric
    and (center->>1)::numeric>=(bounds->>1)::numeric and (center->>1)::numeric<(bounds->>3)::numeric order by id loop
    changes:='{}'; payload:=fauxlore.province_payload(p);
    for i in 0..jsonb_array_length(rules)-1 loop
      rule:=rules->i; expected:=rule->'condition_value';
      if fauxlore.layer_for(rule->>'condition_field') is not null then
        actual:=coalesce(payload->'layers'->fauxlore.layer_for(rule->>'condition_field')->'name','null');
      else
        actual:=coalesce(payload->(case rule->>'condition_field' when 'capital' then 'has_capital_marker' when 'city' then 'has_city_marker' else rule->>'condition_field' end),'null');
      end if;
      if lower(actual::text)<>lower(expected::text) then continue; end if;
      count_i:=(counts->>i)::integer+1; counts:=jsonb_set(counts,array[i::text],to_jsonb(count_i));
      if changes?(rule->>'target_field') and changes->(rule->>'target_field')<>rule->'target_value' then
        if not conflict_ids@>jsonb_build_array(p.id) then conflicts:=conflicts+1; conflict_ids:=conflict_ids||to_jsonb(p.id); end if;
      end if;
      changes:=changes||jsonb_build_object(rule->>'target_field',rule->'target_value');
    end loop;
    if changes<>'{}' then total:=total+1; merged:=merged||jsonb_build_object(p.id::text,changes); end if;
  end loop;
  if not apply_changes then return jsonb_build_object('rule_counts',counts,'total',total,'conflict_count',conflicts,'conflict_examples',conflict_ids); end if;
  if conflicts>0 then raise sqlstate '22023' using message='Правила пересекаются и задают разные значения одному параметру'; end if;
  for entry in select * from jsonb_each(merged) order by key::integer loop perform fauxlore.edit_province(entry.key::integer,entry.value); end loop;
  return jsonb_build_object('updated_count',total,'rule_counts',counts);
end $$;

-- The sole privileged dispatcher. Its read-only public routes return only the
-- public map. Every other operation checks auth.uid() and a database-owned role.
create or replace function fauxlore.api(path text, method text, body jsonb, request_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; p fauxlore.provinces; m fauxlore.map_markers; result jsonb;
  previous fauxlore.operations; fingerprint text; id_value integer; marker_id bigint; state_value integer;
  avatar text; mime_value text; changes jsonb;
begin
  if length(path)>150 or method not in ('GET','POST','PATCH','PUT','DELETE') or
    jsonb_typeof(body) is distinct from 'object' or octet_length(body::text)>2900000 then
    raise sqlstate '22023' using message='Некорректный запрос'; end if;
  if path='health' and method='GET' then return jsonb_build_object('ok',true,'database','supabase'); end if;
  if path='map' and method='GET' then
    if not exists(select 1 from fauxlore._settings where key='migration_ready' and value_json='true') then
      raise sqlstate '55000' using message='Перенос данных ещё не завершён'; end if;
    return fauxlore.map_payload();
  end if;
  if path='auth/me' and method='GET' and auth.uid() is null then return '{"user":null}'; end if;
  a:=fauxlore.current_account();
  if path like 'admin/%' and a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  if path='auth/me' and method='GET' then return jsonb_build_object('user',fauxlore.profile(a)); end if;
  if path='profile' and method='GET' then return fauxlore.profile(a); end if;
  if path='preferences' and method='GET' then return coalesce((select settings from fauxlore.user_preferences where account_id=a.id),'{}'); end if;
  if method='GET' then raise sqlstate 'P0002' using message='Метод API не найден'; end if;
  if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
  fingerprint:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into previous from fauxlore.operations o where account_id=a.id and o.request_id=api.request_id;
  if found then
    if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if;
    return previous.result;
  end if;
  if path='preferences' and method='PUT' then
    select coalesce(jsonb_object_agg(key,value),'{}') into changes from jsonb_each(body) where key=any(array['layer','markers','information','showIds']);
    if octet_length(changes::text)>8192 then raise sqlstate '22023' using message='Слишком большой набор настроек'; end if;
    insert into fauxlore.user_preferences values(a.id,changes) on conflict(account_id) do update set settings=excluded.settings;
    result:='{"ok":true}';
  elsif path='profile/avatar' and method='POST' then
    avatar:=body->>'image_data';
    if avatar is not null then
      if avatar!~'^data:image/(png|jpeg|gif|webp);base64,[A-Za-z0-9+/=\r\n]+$' then raise sqlstate '22023' using message='Неподдерживаемое изображение'; end if;
      mime_value:=split_part(substr(avatar,6),';',1);avatar:=split_part(avatar,',',2);
      if octet_length(decode(avatar,'base64'))>2097152 then raise sqlstate '22023' using message='Аватар должен быть не больше 2 МБ'; end if;
    end if;
    update fauxlore.accounts set avatar_base64=avatar,avatar_type=mime_value where id=a.id;
    result:='{"ok":true}';
  elsif path~'^admin/categories/(states|races|religions|resources|trade|climate)/[0-9]+$' and method='PATCH' then
    if body-'color'<>'{}' or jsonb_typeof(body->'color') is distinct from 'string' or
      (body->>'color')!~'^#[0-9a-fA-F]{6}$' then
      raise sqlstate '22023' using message='Укажите цвет в формате #RRGGBB'; end if;
    update fauxlore.map_categories set color=lower(body->>'color')
      where layer=split_part(path,'/',3) and id=split_part(path,'/',4)::integer
      returning to_jsonb(map_categories.*) into result;
    if not found then raise sqlstate 'P0002' using message='Значение параметра не найдено'; end if;
  elsif path='admin/roads' and method='POST' then
    result:=fauxlore.create_road(body,a.id);
  elsif path~'^admin/roads/[0-9]+$' and method='DELETE' then
    marker_id:=split_part(path,'/',3)::bigint;delete from fauxlore.map_roads where id=marker_id;
    if not found then raise sqlstate 'P0002' using message='Дорога не найдена'; end if;
    result:=jsonb_build_object('id',marker_id,'deleted',true);
  elsif path in ('admin/provinces/bulk-preview','admin/provinces/bulk-edit') and method='POST' then
    result:=fauxlore.bulk_edit(body,path='admin/provinces/bulk-edit');
  elsif path~'^admin/provinces/\d+$' and method='PATCH' then
    result:=fauxlore.edit_province(split_part(path,'/',3)::integer,body);
  elsif path~'^provinces/\d+/name$' and method='PATCH' then
    id_value:=split_part(path,'/',2)::integer;
    if not exists(select 1 from fauxlore.province_values v join fauxlore.account_states s
      on s.state_id=v.category_id and s.account_id=a.id where v.province_id=id_value and v.layer='states') then
      raise sqlstate '42501' using message='Вы не владеете государством этой провинции'; end if;
    if body-'name'<>'{}' then raise sqlstate '22023' using message='Разрешено менять только название'; end if;
    result:=fauxlore.edit_province(id_value,body);result:=jsonb_build_object('id',id_value,'name',result->'name');
  elsif path='admin/markers' and method='POST' then
    if body-array['province_id','x','y','type','name','state_id']<>'{}' or body->>'type' not in ('capital','city','fortress','port') then
      raise sqlstate '22023' using message='Некорректный маркер'; end if;
    select * into p from fauxlore.provinces where id=(body->>'province_id')::integer;
    if not found then raise sqlstate 'P0002' using message='Провинция не найдена'; end if;
    if jsonb_typeof(body->'x') is distinct from 'number' or jsonb_typeof(body->'y') is distinct from 'number' or
      (body->>'x')::numeric<(p.bbox->>0)::numeric or (body->>'x')::numeric>=(p.bbox->>2)::numeric or
      (body->>'y')::numeric<(p.bbox->>1)::numeric or (body->>'y')::numeric>=(p.bbox->>3)::numeric then
      raise sqlstate '22023' using message='Точка не совпадает с выбранной провинцией'; end if;
    state_value:=(body->>'state_id')::integer;
    if state_value is null then select category_id into state_value from fauxlore.province_values where province_id=p.id and layer='states'; end if;
    insert into fauxlore.map_markers(province_id,x,y,type,name,state_id)
      values(p.id,(body->>'x')::float8,(body->>'y')::float8,body->>'type',fauxlore.normalize('name',body->'name')#>>'{}',state_value) returning * into m;
    result:=to_jsonb(m)||jsonb_build_object('state_name',(select name from fauxlore.map_categories where layer='states' and id=m.state_id));
  elsif path~'^admin/markers/\d+$' and method='DELETE' then
    marker_id:=split_part(path,'/',3)::bigint; delete from fauxlore.map_markers where id=marker_id;
    if not found then raise sqlstate 'P0002' using message='Маркер не найден'; end if;
    result:=jsonb_build_object('id',marker_id,'deleted',true);
  else raise sqlstate 'P0002' using message='Метод API не найден';
  end if;
  if path like 'admin/provinces/%' and path<>'admin/provinces/bulk-preview' or path like 'admin/markers%' or path like 'admin/categories/%' or path like 'admin/roads%' or path like 'provinces/%' then
    update fauxlore._settings set value_json=to_jsonb((value_json#>>'{}')::bigint+1) where key='data_revision';
  end if;
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,api.request_id,fingerprint,result);
  return result;
end $$;

create or replace function fauxlore.turn_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; calendar_row fauxlore.game_calendar; previous fauxlore.operations;
  fingerprint text; result jsonb; report_value jsonb; character_row record;
  age_value integer; death_chance numeric; died boolean; dead_ruler_count integer:=0; advanced_character_count integer:=0;
begin
  if path='game/calendar' and method='GET' then
    select * into calendar_row from fauxlore.game_calendar where singleton=true;
    return jsonb_build_object('year',calendar_row.year,'turn',calendar_row.turn);
  end if;
  if path<>'admin/turn/advance' or method<>'POST' or body-array['expected_year','expected_turn','report']<>'{}' or
    jsonb_typeof(body->'report') is distinct from 'array' or octet_length(coalesce(body->'report','[]'::jsonb)::text)>1500000 then
    raise sqlstate '22023' using message='Некорректный запрос смены хода'; end if;
  a:=fauxlore.current_account();
  if a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
  fingerprint:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=turn_api.request_id;
  if found then
    if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if;
    return previous.result;
  end if;
  select * into calendar_row from fauxlore.game_calendar where singleton=true for update;
  if calendar_row.year<>(body->>'expected_year')::integer or calendar_row.turn<>(body->>'expected_turn')::integer then
    raise sqlstate '40001' using message='Ход уже изменён в другой сессии. Обновите страницу и повторите.'; end if;
  report_value:=body->'report';
  insert into fauxlore.turn_economy_reports(year,turn,report,created_by) values(calendar_row.year,calendar_row.turn,report_value,a.id);
  for character_row in
    select ch.id,ch.state_id,ch.age,ch.name,ch.surname,ch.is_current_ruler,coalesce(rc.name,'') as race_name
    from fauxlore.state_characters ch
    left join fauxlore.map_categories rc on rc.layer='races' and rc.id=ch.race_id
    where ch.alive order by ch.id for update of ch
  loop
    age_value:=least(250,character_row.age+1);
    death_chance:=case
      when character_row.race_name in ('Люди','Полуэльфы','Зверолюди') then
        case when age_value<60 then 0 when age_value<=70 then .05 when age_value<=80 then .15
          when age_value<=90 then .25 when age_value<=100 then .50 else .70 end
      when character_row.race_name='Дварфы' then
        case when age_value<80 then 0 when age_value<=90 then .05 when age_value<=100 then .15
          when age_value<=110 then .25 when age_value<=120 then .50 else .70 end
      when character_row.race_name='Эльфы' then
        case when age_value<100 then 0 when age_value<=120 then .05 when age_value<=140 then .15
          when age_value<=160 then .25 when age_value<=180 then .50 else .70 end
      else 0 end;
    died:=death_chance>0 and random()<death_chance;
    update fauxlore.state_characters set age=age_value,alive=not died,
      died_at_turn=case when died then calendar_row.turn else died_at_turn end,
      is_current_ruler=case when died and character_row.is_current_ruler then false else is_current_ruler end
    where id=character_row.id;
    advanced_character_count:=advanced_character_count+1;
    if died and character_row.is_current_ruler then
      dead_ruler_count:=dead_ruler_count+1;
      insert into fauxlore.notifications(account_id,kind,title,message)
      select recipients.account_id,'ruler_death','Умер правитель государства',
        'Правитель '||trim(character_row.name||' '||character_row.surname)||' умер в возрасте '||age_value||' лет. Требуется провести передачу власти.'
      from (
        select distinct ast.account_id from fauxlore.account_states ast
        where ast.layer='states' and ast.state_id=character_row.state_id
        union
        select ac.id from fauxlore.accounts ac where ac.role='admin'
          and not exists(select 1 from fauxlore.account_states ast where ast.layer='states' and ast.state_id=character_row.state_id)
      ) recipients;
    end if;
  end loop;
  update fauxlore.game_calendar set year=year+1,turn=turn+1,updated_at=now() where singleton=true returning * into calendar_row;
  result:=jsonb_build_object('year',calendar_row.year,'turn',calendar_row.turn,
    'calculated_year',calendar_row.year-1,'calculated_turn',calendar_row.turn-1,'states_calculated',jsonb_array_length(report_value),
    'characters_aged',advanced_character_count,'rulers_died',dead_ruler_count);
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,turn_api.request_id,fingerprint,result);
  return result;
end $$;
revoke all on function fauxlore.turn_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.turn_api(text,text,jsonb,uuid) to anon,authenticated;

create or replace function public.fauxlore_api(path text, method text default 'GET', body jsonb default '{}', request_id uuid default null)
returns jsonb language sql security invoker set search_path='' as $$
  select case when path='game/calendar' or path='admin/turn/advance' then fauxlore.turn_api(path,method,body,request_id)
    when path='admin/states' then fauxlore.state_api(path,method,body,request_id)
    when path='my/states' or path like 'admin/states/%' then fauxlore.game_state_api(path,method,body,request_id)
    else fauxlore.api(path,method,body,request_id) end
$$;
revoke all on all functions in schema fauxlore from public, anon, authenticated;
grant usage on schema fauxlore to anon, authenticated;
grant execute on function fauxlore.api(text,text,jsonb,uuid) to anon, authenticated;
revoke all on function public.fauxlore_api(text,text,jsonb,uuid) from public;
grant execute on function public.fauxlore_api(text,text,jsonb,uuid) to anon, authenticated;
-- Supabase's default event-trigger helper need not be callable through REST.
do $$ begin
  if to_regprocedure('public.rls_auto_enable()') is not null then
    revoke execute on function public.rls_auto_enable() from public,anon,authenticated;
  end if;
end $$;
notify pgrst, 'reload schema';
/*
create table if not exists fauxlore.state_birth_events (
  id bigint generated always as identity primary key,
  state_id integer not null references fauxlore.state_profiles(state_id) on delete cascade,
  year integer not null,
  turn integer not null,
  father_id bigint not null references fauxlore.state_characters(id),
  mother_id bigint not null references fauxlore.state_characters(id),
  children jsonb not null check(jsonb_typeof(children)='array' and jsonb_array_length(children) between 1 and 3),
  named_at timestamptz,
  created_at timestamptz not null default now(),
  unique(state_id,year)
);
create index if not exists state_birth_events_pending_idx on fauxlore.state_birth_events(state_id,year) where named_at is null;

create table if not exists fauxlore.state_marriage_candidates (
  id bigint generated always as identity primary key,
  state_id integer not null references fauxlore.state_profiles(state_id) on delete cascade,
  created_turn integer not null,
  name text not null,
  surname text not null default '',
  gender text not null check(gender in ('Мужской','Женский')),
  age smallint not null check(age between 18 and 59),
  race_id integer not null,
  religion_id integer not null,
  supported_by text[] not null default '{}',
  selected_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists state_marriage_candidates_current_idx on fauxlore.state_marriage_candidates(state_id,created_turn) where selected_at is null;
alter table fauxlore.state_birth_events enable row level security;
alter table fauxlore.state_marriage_candidates enable row level security;
revoke all on fauxlore.state_birth_events,fauxlore.state_marriage_candidates from public,anon,authenticated;

create or replace function fauxlore.process_annual_births()
returns trigger language plpgsql security definer set search_path='' as $$
declare couple record; child_count integer; child_race integer; children_value jsonb; mother_death_chance numeric; mother_died boolean;
  child_index integer; is_lawful boolean; father_race text; mother_race text; authority_name text; birth_roll numeric;
begin
  if new.year=old.year then return new; end if;
  for couple in
    select sp.state_id,sp.principles,sp.official_race_id,sp.official_religion_id,
      ruler.id ruler_id,ruler.name ruler_name,ruler.surname ruler_surname,ruler.gender ruler_gender,ruler.age ruler_age,
      ruler.race_id ruler_race_id,ruler.religion_id ruler_religion_id,
      spouse.id spouse_id,spouse.gender spouse_gender,spouse.age spouse_age,spouse.race_id spouse_race_id,
      spouse.religion_id spouse_religion_id,
      case when m.character_a_id=ruler.id then m.lawful_for_a else m.lawful_for_b end lawful_for_ruler,
      coalesce(ruler_race.name,'') ruler_race,coalesce(spouse_race.name,'') spouse_race
    from fauxlore.state_profiles sp
    join fauxlore.state_characters ruler on ruler.state_id=sp.state_id and ruler.is_current_ruler and ruler.alive
    join fauxlore.state_marriages m on m.ended_at_turn is null and ruler.id in (m.character_a_id,m.character_b_id)
    join fauxlore.state_characters spouse on spouse.id=case when m.character_a_id=ruler.id then m.character_b_id else m.character_a_id end and spouse.alive
    left join fauxlore.map_categories ruler_race on ruler_race.layer='races' and ruler_race.id=ruler.race_id
    left join fauxlore.map_categories spouse_race on spouse_race.layer='races' and spouse_race.id=spouse.race_id
    where (ruler.gender='Мужской' and ruler.age<60 and spouse.gender='Женский' and spouse.age<45)
       or (ruler.gender='Женский' and ruler.age<45 and spouse.gender='Мужской' and spouse.age<60)
  loop
    father_race:=case when couple.ruler_gender='Мужской' then couple.ruler_race else couple.spouse_race end;
    mother_race:=case when couple.ruler_gender='Женский' then couple.ruler_race else couple.spouse_race end;
    if father_race=mother_race and father_race in ('Люди','Эльфы','Дварфы','Зверолюди') then
      child_race:=case when couple.ruler_gender='Мужской' then couple.ruler_race_id else couple.spouse_race_id end;
    elsif father_race in ('Люди','Эльфы','Полуэльфы') and mother_race in ('Люди','Эльфы','Полуэльфы') then
      child_race:=case when father_race='Люди' and mother_race='Люди' then (select id from fauxlore.map_categories where layer='races' and name='Люди' limit 1)
        when father_race='Эльфы' and mother_race='Эльфы' then (select id from fauxlore.map_categories where layer='races' and name='Эльфы' limit 1)
        else (select id from fauxlore.map_categories where layer='races' and name='Полуэльфы' limit 1) end;
    else continue;
    end if;
    if child_race is null or random()>=.25 then continue; end if;
    birth_roll:=random();
    child_count:=case when birth_roll<.94 then 1 when birth_roll<.99 then 2 else 3 end;
    authority_name:=coalesce(couple.principles->>'authority','');
    is_lawful:=authority_name='Династия' and couple.lawful_for_ruler;
    children_value:='[]'::jsonb;
    for child_index in 1..child_count loop
      children_value:=children_value||jsonb_build_array(jsonb_build_object(
        'gender',case when random()<.5 then 'Мужской' else 'Женский' end,
        'race_id',child_race,
        'religion_id',case when random()<.5 then case when couple.ruler_gender='Мужской' then couple.ruler_religion_id else couple.spouse_religion_id end
          else case when couple.ruler_gender='Женский' then couple.ruler_religion_id else couple.spouse_religion_id end end,
        'legitimacy',case when authority_name='Династия' then case when is_lawful then 'Законный' else 'Незаконный' end else 'Неприменимо' end));
    end loop;
    mother_died:=false;
    mother_death_chance:=case when (case when couple.ruler_gender='Женский' then couple.ruler_age else couple.spouse_age end)<35 then .01
      when (case when couple.ruler_gender='Женский' then couple.ruler_age else couple.spouse_age end)<40 then .03 else .07 end
      +case when child_count=2 then .02 when child_count=3 then .04 else 0 end;
    mother_death_chance:=least(.10,mother_death_chance);
    mother_died:=random()<mother_death_chance;
    insert into fauxlore.state_birth_events(state_id,year,turn,father_id,mother_id,children)
    values(couple.state_id,new.year,new.turn,
      case when couple.ruler_gender='Мужской' then couple.ruler_id else couple.spouse_id end,
      case when couple.ruler_gender='Женский' then couple.ruler_id else couple.spouse_id end,children_value);
    if mother_died then
      update fauxlore.state_characters set alive=false,died_at_turn=new.turn,is_current_ruler=false
      where id=case when couple.ruler_gender='Женский' then couple.ruler_id else couple.spouse_id end;
    end if;
    insert into fauxlore.notifications(account_id,kind,title,message)
    select recipients.account_id,'birth','Рождение в семье правителя',
      'В семье государства родилось детей: '||child_count||'. Откройте вкладку «Власть и династия», чтобы указать имена.'||
      case when mother_died then ' Мать детей умерла при родах.' else '' end
    from (select distinct ast.account_id from fauxlore.account_states ast where ast.layer='states' and ast.state_id=couple.state_id
      union select ac.id from fauxlore.accounts ac where ac.role='admin' and not exists(select 1 from fauxlore.account_states ast where ast.layer='states' and ast.state_id=couple.state_id)) recipients;
  end loop;
  return new;
end $$;
revoke all on function fauxlore.process_annual_births() from public,anon,authenticated;
drop trigger if exists game_calendar_process_births on fauxlore.game_calendar;
create trigger game_calendar_process_births after update of year on fauxlore.game_calendar
for each row when (new.year is distinct from old.year) execute function fauxlore.process_annual_births();

create or replace function fauxlore.character_lifecycle_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; state_value integer; birth_value bigint; candidate_value bigint; state_row fauxlore.state_profiles;
  ruler fauxlore.state_characters; event_row fauxlore.state_birth_events; calendar_row fauxlore.game_calendar;
  result jsonb; fingerprint text; previous fauxlore.operations; names_value jsonb; child jsonb; candidate fauxlore.state_marriage_candidates; spouse_row fauxlore.state_characters;
  gender_value text; race_values integer[]; candidate_names text[]; candidate_surnames text[]; candidate_religion integer;
  candidate_race integer; candidate_age integer; support_value text[]; i integer; ruler_race_name text; authority_name text;
begin
  a:=fauxlore.current_account();
  if path !~ '^my/states/[0-9]+/(birth-events|birth-events/[0-9]+/name|marriage-candidates|marriages/local)$' then
    raise sqlstate '22023' using message='Некорректный запрос'; end if;
  state_value:=split_part(path,'/',3)::integer;
  if not exists(select 1 from fauxlore.account_states ast where ast.account_id=a.id and ast.layer='states' and ast.state_id=state_value) then
    raise sqlstate '42501' using message='Нет доступа к этому государству'; end if;
  select * into state_row from fauxlore.state_profiles where state_id=state_value;
  if not found then raise sqlstate 'P0002' using message='Государство не найдено'; end if;
  if path ~ '/birth-events/[0-9]+/name$' and method='POST' then
    birth_value:=split_part(path,'/',5)::bigint;
    if body-'names'<>'{}'::jsonb or jsonb_typeof(body->'names') is distinct from 'array' then raise sqlstate '22023' using message='Передайте список имён'; end if;
    if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
    fingerprint:=md5(jsonb_build_array(method,path,body)::text);
    perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
    select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=character_lifecycle_api.request_id;
    if found then if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if; return previous.result; end if;
    select * into event_row from fauxlore.state_birth_events where id=birth_value and state_id=state_value for update;
    if not found or event_row.named_at is not null then raise sqlstate 'P0002' using message='Событие рождения уже обработано или не найдено'; end if;
    names_value:=body->'names';
    if jsonb_array_length(names_value)<>jsonb_array_length(event_row.children) or exists(select 1 from jsonb_array_elements_text(names_value) x where length(btrim(x)) not between 1 and 120) then
      raise sqlstate '22023' using message='Укажите имя длиной от 1 до 120 символов для каждого ребёнка'; end if;
    for i in 0..jsonb_array_length(event_row.children)-1 loop
      child:=event_row.children->i;
      insert into fauxlore.state_characters(state_id,name,surname,gender,age,race_id,religion_id,legitimacy,father_id,mother_id)
      values(state_value,btrim(names_value->>i),coalesce((select surname from fauxlore.state_characters where id=event_row.father_id),''),
        child->>'gender',0,(child->>'race_id')::integer,(child->>'religion_id')::integer,child->>'legitimacy',event_row.father_id,event_row.mother_id);
    end loop;
    update fauxlore.state_birth_events set named_at=now() where id=birth_value;
    result:=jsonb_build_object('named',jsonb_array_length(names_value),'birth_id',birth_value);
    insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,character_lifecycle_api.request_id,fingerprint,result);
    return result;
  elsif path='my/states/'||state_value||'/birth-events' and method='GET' and body='{}'::jsonb then
    select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'year',e.year,'turn',e.turn,'children',e.children) order by e.year,e.id),'[]'::jsonb)
      into result from fauxlore.state_birth_events e where e.state_id=state_value and e.named_at is null;
    return result;
  elsif path='my/states/'||state_value||'/marriage-candidates' and method='GET' and body='{}'::jsonb then
    select * into ruler from fauxlore.state_characters where state_id=state_value and is_current_ruler and alive;
    if not found then return jsonb_build_object('candidates','[]'::jsonb,'message','Сейчас в государстве нет действующего правителя.'); end if;
    if exists(select 1 from fauxlore.state_marriages where ended_at_turn is null and ruler.id in(character_a_id,character_b_id)) then
      return jsonb_build_object('candidates','[]'::jsonb,'message','У правителя уже есть супруг.'); end if;
    if state_row.prestige<10 then return jsonb_build_object('candidates','[]'::jsonb,'message','Для местного брака требуется 10 ОП.'); end if;
    select * into calendar_row from fauxlore.game_calendar where singleton=true;
    perform pg_advisory_xact_lock(hashtextextended('marriage-candidates:'||state_value::text,0));
    if not exists(select 1 from fauxlore.state_marriage_candidates where state_id=state_value and created_turn=calendar_row.turn and selected_at is null) then
      gender_value:=case when ruler.gender='Мужской' then 'Женский' else 'Мужской' end;
      select name into ruler_race_name from fauxlore.map_categories where layer='races' and id=ruler.race_id;
      race_values:=array(select id from fauxlore.map_categories where layer='races' and name=any(
        case ruler_race_name when 'Люди' then array['Люди','Эльфы','Полуэльфы'] when 'Эльфы' then array['Люди','Эльфы','Полуэльфы']
          when 'Полуэльфы' then array['Люди','Эльфы','Полуэльфы'] when 'Дварфы' then array['Дварфы'] when 'Зверолюди' then array['Зверолюди'] else array[ruler_race_name] end));
      candidate_names:=case when gender_value='Женский' then array['Алиса','Велена','Дарья','Елена','Ирина','Лада','Мира','Надежда','Рада','Ярослава'] else array['Алексей','Борис','Владимир','Глеб','Дамир','Илья','Мирослав','Ратибор','Святослав','Яромир'] end;
      candidate_surnames:=array['Белоярский','Ветров','Зорин','Каменев','Лесной','Руднев','Серебряков','Сумеречный'];
      authority_name:=coalesce(state_row.principles->>'authority','');
      support_value:=case authority_name when 'Династия' then array['Корона','Знать'] when 'Магистрат' then array['Духовенство','Горожане']
        when 'Клир' then array['Духовенство'] when 'Диктат' then array['Корона'] when 'Вече' then array['Горожане','Крестьяне','Духовенство']
        else array['Корона','Знать','Духовенство','Горожане','Крестьяне'] end;
      for i in 1..3 loop
        candidate_race:=race_values[1+floor(random()*cardinality(race_values))::integer];
        select id into candidate_religion from fauxlore.map_categories where layer='religions' order by random() limit 1;
        candidate_age:=case when gender_value='Женский' then 18+floor(random()*27)::integer else 18+floor(random()*42)::integer end;
        insert into fauxlore.state_marriage_candidates(state_id,created_turn,name,surname,gender,age,race_id,religion_id,supported_by)
        values(state_value,calendar_row.turn,candidate_names[1+floor(random()*cardinality(candidate_names))::integer],candidate_surnames[1+floor(random()*cardinality(candidate_surnames))::integer],gender_value,candidate_age,candidate_race,candidate_religion,
          case when random()<.34 then array[support_value[1+floor(random()*cardinality(support_value))::integer]] else '{}'::text[] end);
      end loop;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'surname',c.surname,'gender',c.gender,'age',c.age,
      'race',(select name from fauxlore.map_categories where layer='races' and id=c.race_id),
      'religion',(select name from fauxlore.map_categories where layer='religions' and id=c.religion_id),'supported_by',c.supported_by) order by c.id),'[]'::jsonb)
      into result from fauxlore.state_marriage_candidates c where c.state_id=state_value and c.created_turn=calendar_row.turn and c.selected_at is null;
    return jsonb_build_object('candidates',result,'message','Выберите кандидата. Заключение местного брака стоит 10 ОП.');
  elsif path='my/states/'||state_value||'/marriages/local' and method='POST' then
    if body-'candidate_id'<>'{}'::jsonb or coalesce(body->>'candidate_id','') !~ '^\d+$' then raise sqlstate '22023' using message='Некорректный кандидат'; end if;
    if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
    fingerprint:=md5(jsonb_build_array(method,path,body)::text);
    perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
    select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=character_lifecycle_api.request_id;
    if found then if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if; return previous.result; end if;
    select * into ruler from fauxlore.state_characters where state_id=state_value and is_current_ruler and alive for update;
    select * into calendar_row from fauxlore.game_calendar where singleton=true;
    select * into candidate from fauxlore.state_marriage_candidates where id=(body->>'candidate_id')::bigint and state_id=state_value and created_turn=calendar_row.turn and selected_at is null for update;
    if not found then raise sqlstate 'P0002' using message='Кандидат устарел. Обновите список.'; end if;
    if ruler.id is null then raise sqlstate 'P0002' using message='Нет действующего правителя'; end if;
    if exists(select 1 from fauxlore.state_marriages where ended_at_turn is null and ruler.id in(character_a_id,character_b_id)) then raise sqlstate '22023' using message='У правителя уже есть супруг'; end if;
    if state_row.prestige<10 then raise sqlstate '22023' using message='Для местного брака требуется 10 ОП'; end if;
    authority_name:=coalesce(state_row.principles->>'authority','');
    select * into state_row from fauxlore.state_profiles where state_id=state_value for update;
    if state_row.prestige<10 then raise sqlstate '22023' using message='Для местного брака требуется 10 ОП'; end if;
    insert into fauxlore.state_characters(state_id,name,surname,gender,age,race_id,religion_id,legitimacy)
    values(state_value,candidate.name,candidate.surname,candidate.gender,candidate.age,candidate.race_id,candidate.religion_id,'Неприменимо') returning * into spouse_row;
    insert into fauxlore.state_marriages(character_a_id,character_b_id,marriage_type,lawful_for_a,lawful_for_b,started_at_turn)
    values(ruler.id,spouse_row.id,'local',authority_name='Династия',authority_name='Династия',calendar_row.turn);
    update fauxlore.state_marriage_candidates set selected_at=now() where id=(body->>'candidate_id')::bigint;
    update fauxlore.state_profiles set prestige=prestige-10 where state_id=state_value;
    result:=jsonb_build_object('married',true,'spouse_id',spouse_row.id,'cost',10);
    insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,character_lifecycle_api.request_id,fingerprint,result);
    insert into fauxlore.notifications(account_id,kind,title,message) values(a.id,'marriage','Заключён местный брак','Правитель заключил местный брак. Потрачено 10 ОП.');
    return result;
  end if;
  raise sqlstate '22023' using message='Недопустимый запрос';
end $$;
revoke all on function fauxlore.character_lifecycle_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.character_lifecycle_api(text,text,jsonb,uuid) to authenticated;

create or replace function fauxlore.province_value_for_state(target_province integer,target_state integer)
returns numeric language plpgsql stable security definer set search_path='' as $$
declare p fauxlore.provinces; cfg jsonb; state_name text; owner_state integer;
  race_name text; religion_name text; resource_name text; tax_mod numeric; prod_mod numeric;
  trade_mod numeric; trade_base numeric; trade_status_mod numeric; race_rate numeric; religion_rate numeric;
  resource_value numeric:=0; resource_prod numeric:=0; crime_rate numeric:=.2;
  share numeric:=0; control_value numeric; population numeric; tax_value numeric; production_value numeric;
  trade_value numeric; recruit_limit numeric; weights jsonb;
begin
  select * into p from fauxlore.provinces where id=target_province and kind='land';
  if not found then return null; end if;
  select config into cfg from fauxlore.economy_parameters where singleton=true;
  select c.name into state_name from fauxlore.map_categories c where c.layer='states' and c.id=target_state;
  select category_id into owner_state from fauxlore.province_values where province_id=p.id and layer='states';
  select c.name into race_name from fauxlore.province_values v join fauxlore.map_categories c on c.layer=v.layer and c.id=v.category_id where v.province_id=p.id and v.layer='races';
  select c.name into religion_name from fauxlore.province_values v join fauxlore.map_categories c on c.layer=v.layer and c.id=v.category_id where v.province_id=p.id and v.layer='religions';
  select c.name into resource_name from fauxlore.province_values v join fauxlore.map_categories c on c.layer=v.layer and c.id=v.category_id where v.province_id=p.id and v.layer='resources';
  if race_name is null or religion_name is null or state_name is null then return null; end if;
  if p.occupation is not null and (owner_state is null or lower(p.occupation)<>lower((select name from fauxlore.map_categories where layer='states' and id=owner_state))) then
    if lower(p.occupation)=lower(state_name) then share:=coalesce((cfg->>'occupationMultiplier')::numeric,.5); end if;
  elsif owner_state=target_state then share:=1;
  end if;
  if share=0 then return 0; end if;
  tax_mod:=nullif(cfg#>>array['provinceModifiers',p.province_type,'tax'],'')::numeric;
  prod_mod:=nullif(cfg#>>array['provinceModifiers',p.province_type,'production'],'')::numeric;
  trade_mod:=nullif(cfg#>>array['provinceModifiers',p.province_type,'trade'],'')::numeric;
  trade_base:=nullif(cfg#>>array['provinceModifiers',p.province_type,'tradeBase'],'')::numeric;
  race_rate:=nullif(cfg#>>array['raceTaxRates',race_name],'')::numeric;
  religion_rate:=nullif(cfg#>>array['religionTaxRates',religion_name],'')::numeric;
  trade_status_mod:=nullif(cfg#>>array['tradeStatusModifiers',coalesce(p.trade_status,'Отсутствует')],'')::numeric;
  if tax_mod is null or prod_mod is null or trade_mod is null or trade_base is null or race_rate is null or religion_rate is null or trade_status_mod is null then return null; end if;
  select coalesce((r->>'value')::numeric,0),coalesce((r->>'production')::numeric,0) into resource_value,resource_prod
    from jsonb_array_elements(cfg->'resources') r where r->>'name'=resource_name limit 1;
  select coalesce(crime,.2) into crime_rate from fauxlore.state_profiles where state_id=target_state;
  crime_rate:=coalesce(crime_rate,.2); population:=greatest(0,p.population)::numeric;
  control_value:=coalesce(p.control,100)::numeric/100;
  tax_value:=round(population/10*(race_rate+religion_rate)*tax_mod*control_value*share,2);
  production_value:=round(population*resource_prod*prod_mod*control_value*(1-crime_rate)*share,0);
  trade_value:=round(trade_base*trade_mod*trade_status_mod*share,2);
  recruit_limit:=round(population/100
    *coalesce((cfg#>>array['recruitLimitModifiers',p.province_type])::numeric,0)
    *case when p.belonging='Отсутствует' then 0 else coalesce((cfg#>>array['estateRecruitModifiers',p.belonging])::numeric,0) end
    *control_value*share,0);
  weights:=cfg->'provinceValueWeights';
  return round(((tax_value+production_value*resource_value)*coalesce((weights->>'gold')::numeric,0))
    +(trade_value*coalesce((weights->>'trade')::numeric,0))
    +(production_value*resource_value*coalesce((weights->>'production')::numeric,0))
    +(recruit_limit*coalesce((weights->>'recruits')::numeric,0))
    +(population*coalesce((weights->>'population')::numeric,0)*share),0);
end $$;
revoke all on function fauxlore.province_value_for_state(integer,integer) from public,anon,authenticated;

create or replace function fauxlore.economy_config_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; old_config jsonb; next_config jsonb; prior fauxlore.operations; fp text; item jsonb; pair record; key_name text; result jsonb;
begin
  if path='economy/config' and method='GET' then return (select config from fauxlore.economy_parameters where singleton=true); end if;
  if path not in ('admin/economy/config','economy/config') then raise sqlstate 'P0002' using message='Метод API не найден'; end if;
  a:=fauxlore.current_account();
  if a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  select config into old_config from fauxlore.economy_parameters where singleton=true for update;
  if path='admin/economy/config' and method='GET' then return old_config; end if;
  if path<>'admin/economy/config' or method<>'PATCH' or request_id is null or body-'config'<>'{}' or jsonb_typeof(body->'config') is distinct from 'object' then
    raise sqlstate '22023' using message='Некорректное изменение параметров экономики'; end if;
  fp:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into prior from fauxlore.operations where account_id=a.id and fauxlore.operations.request_id=economy_config_api.request_id;
  if found then if prior.fingerprint<>fp then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if; return prior.result; end if;
  next_config:=body->'config';
  if (select array_agg(k order by k) from jsonb_object_keys(next_config) k)<>
     (select array_agg(k order by k) from jsonb_object_keys(old_config) k) or next_config->'occupationMultiplier'<>'0.5'::jsonb then
    raise sqlstate '22023' using message='Набор параметров или коэффициент оккупации изменён'; end if;
  foreach key_name in array array['raceTaxRates','religionTaxRates','tradeStatusModifiers','raceGrowthModifiers','recruitGrowthModifiers','recruitLimitModifiers','estateRecruitModifiers','provinceValueWeights'] loop
    if (select array_agg(k order by k) from jsonb_object_keys(next_config->key_name) k)<>
       (select array_agg(k order by k) from jsonb_object_keys(old_config->key_name) k) then raise sqlstate '22023' using message='Изменён состав справочника коэффициентов'; end if;
    for pair in select key,value from jsonb_each(next_config->key_name) loop
      if jsonb_typeof(pair.value)<>'number' or (pair.value#>>'{}')::numeric<0 or (pair.value#>>'{}')::numeric>10000 then
        raise sqlstate '22023' using message='Коэффициент должен быть числом от 0 до 10000'; end if;
    end loop;
  end loop;
  if jsonb_typeof(next_config->'taxLoyaltySensitivity')<>'number' or (next_config->>'taxLoyaltySensitivity')::numeric<0 or (next_config->>'taxLoyaltySensitivity')::numeric>5 then
    raise sqlstate '22023' using message='Чувствительность лояльности должна быть от 0 до 5'; end if;
  if (select array_agg(k order by k) from jsonb_object_keys(next_config->'provinceModifiers') k)<>
     (select array_agg(k order by k) from jsonb_object_keys(old_config->'provinceModifiers') k) then raise sqlstate '22023' using message='Изменён состав типов провинций'; end if;
  for pair in select key,value from jsonb_each(next_config->'provinceModifiers') loop
    if (select array_agg(k order by k) from jsonb_object_keys(pair.value) k)<>
       (select array_agg(k order by k) from jsonb_object_keys(old_config->'provinceModifiers'->pair.key) k) then raise sqlstate '22023' using message='Изменён состав модификатора типа'; end if;
    for key_name in select k from jsonb_object_keys(pair.value) k loop
      if jsonb_typeof(pair.value->key_name)<>'number' or (pair.value->>key_name)::numeric<0 or (pair.value->>key_name)::numeric>10000 then raise sqlstate '22023' using message='Модификатор должен быть числом от 0 до 10000'; end if;
    end loop;
  end loop;
  if jsonb_typeof(next_config->'resources')<>'array' or jsonb_array_length(next_config->'resources')<>jsonb_array_length(old_config->'resources') then raise sqlstate '22023' using message='Изменён состав ресурсов'; end if;
  for item in select value from jsonb_array_elements(next_config->'resources') loop
    if not exists(select 1 from jsonb_array_elements(old_config->'resources') old where old->>'name'=item->>'name' and old->'category'=item->'category' and old->'showInProduction'=item->'showInProduction') then raise sqlstate '22023' using message='Изменены сведения о ресурсе'; end if;
    foreach key_name in array array['value','production','consumption'] loop
      if jsonb_typeof(item->key_name)<>'number' or (item->>key_name)::numeric<0 or (item->>key_name)::numeric>1000000 then raise sqlstate '22023' using message='Параметр ресурса должен быть числом от 0 до 1000000'; end if;
    end loop;
  end loop;
  insert into fauxlore.economy_parameter_history(account_id,before_config,after_config) values(a.id,old_config,next_config);
  update fauxlore.economy_parameters set config=next_config,updated_at=now() where singleton=true;
  result:=jsonb_build_object('config',next_config);
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,request_id,fp,result);
  return result;
end $$;
revoke all on function fauxlore.economy_config_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.economy_config_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst,'reload schema';
+

create or replace function fauxlore.notify_ruler_maternal_death()
returns trigger language plpgsql security definer set search_path='' as $$
begin
  if old.alive and not new.alive and old.is_current_ruler and exists(
    select 1 from fauxlore.state_birth_events e
    join fauxlore.game_calendar c on c.singleton=true and c.year=e.year
    where e.state_id=new.state_id and e.mother_id=new.id
  ) then
    insert into fauxlore.notifications(account_id,kind,title,message)
    select recipients.account_id,'ruler_death','Правительница умерла при родах',
      'Правительница умерла при родах. Требуется передача власти согласно принципу государства.'
    from (select distinct ast.account_id from fauxlore.account_states ast where ast.layer='states' and ast.state_id=new.state_id
      union select ac.id from fauxlore.accounts ac where ac.role='admin' and not exists(
        select 1 from fauxlore.account_states ast where ast.layer='states' and ast.state_id=new.state_id)) recipients;
  end if;
  return new;
end $$;
