create or replace function fauxlore.validate_state_application_connectivity()
returns trigger language plpgsql security definer set search_path='' as $$
declare adjacency_data jsonb; reached_count integer;
begin
  select neighbors into adjacency_data from fauxlore.map_adjacency where singleton;
  if adjacency_data is null then raise sqlstate '55000' using message='Не загружена схема соседства провинций'; end if;
  with recursive selected(id) as (
    select unnest(new.province_ids)
  ), links(a,b) as (
    select a.id,b.id from selected a cross join selected b
    where a.id<>b.id and (
      coalesce(adjacency_data->a.id::text,'[]'::jsonb) @> jsonb_build_array(b.id)
      or coalesce(adjacency_data->b.id::text,'[]'::jsonb) @> jsonb_build_array(a.id)
      or exists(
        select 1 from jsonb_array_elements(coalesce(adjacency_data->a.id::text,'[]'::jsonb)) sea(value)
        join fauxlore.provinces water on water.id=(sea.value#>>'{}')::integer and water.kind='sea'
        where coalesce(adjacency_data->b.id::text,'[]'::jsonb) @> jsonb_build_array(water.id)
      )
    )
  ), reachable(id) as (
    select new.province_ids[1]
    union
    select links.b from reachable join links on links.a=reachable.id
  )
  select count(distinct id) into reached_count from reachable;
  if reached_count<>5 then
    raise sqlstate '22023' using message='Пять провинций должны соседствовать напрямую или через одну морскую провинцию';
  end if;
  return new;
end $$;
revoke all on function fauxlore.validate_state_application_connectivity() from public,anon,authenticated;
drop trigger if exists validate_state_application_connectivity on fauxlore.state_applications;
create trigger validate_state_application_connectivity before insert on fauxlore.state_applications
for each row execute function fauxlore.validate_state_application_connectivity();

create or replace function fauxlore.application_details(path text,method text,body jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; app fauxlore.state_applications;
begin
  if method<>'GET' or path !~ '^my/applications/[0-9]+$' or body<>'{}'::jsonb then
    raise sqlstate '22023' using message='Некорректный запрос анкеты';
  end if;
  a:=fauxlore.current_account();
  select * into app from fauxlore.state_applications
    where id=split_part(path,'/',3)::bigint and account_id=a.id;
  if not found then raise sqlstate 'P0002' using message='Анкета не найдена'; end if;
  return jsonb_build_object('id',app.id,'status',app.status,'state_name',app.state_name,'state_color',app.state_color,
    'principles',app.principles,'ruler_name',app.ruler_name,'ruler_gender',app.ruler_gender,'ruler_title',app.ruler_title,
    'ruler_age',app.ruler_age,'race_id',app.race_id,'religion_id',app.religion_id,'history',app.history,
    'province_ids',to_jsonb(app.province_ids),'capital_province_id',app.capital_province_id,'capital_name',app.capital_name,
    'emblem_type',app.emblem_type,'emblem_base64',app.emblem_base64,'rejection_reason',app.rejection_reason,
    'state_id',app.state_id,'created_at',app.created_at,'reviewed_at',app.reviewed_at);
end $$;
revoke all on function fauxlore.application_details(text,text,jsonb) from public,anon,authenticated;
grant execute on function fauxlore.application_details(text,text,jsonb) to anon,authenticated;

create or replace function public.fauxlore_api(path text,method text default 'GET',body jsonb default '{}',request_id uuid default null)
returns jsonb language sql security invoker set search_path='' as $$
  select case when path like 'my/applications' or path like 'admin/applications%' or path='notifications' or path like 'notifications/%'
      then fauxlore.registration_api(path,method,body,request_id)
    when path ~ '^my/applications/[0-9]+$' then fauxlore.application_details(path,method,body)
    when path ~ '^state-emblem/[0-9]+$' or path ~ '^admin/state-emblem/[0-9]+$' then fauxlore.state_emblem_api(path,method,body,request_id)
    when path='game/calendar' or path='admin/turn/advance' then fauxlore.turn_api(path,method,body,request_id)
    when path='admin/states' then fauxlore.state_api(path,method,body,request_id)
    when path='my/states' or path like 'admin/states/%' then fauxlore.game_state_api(path,method,body,request_id)
    else fauxlore.api(path,method,body,request_id) end
$$;
revoke all on function public.fauxlore_api(text,text,jsonb,uuid) from public;
grant execute on function public.fauxlore_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst,'reload schema';





-- State dashboard access and safe state deletion; mirrored by migration 20261021124326.
create or replace function fauxlore.game_state_api(path text, method text, body jsonb, request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; state_value integer; state_name text; result jsonb;
  previous fauxlore.operations; fingerprint text; province_count integer; removed_assignments integer; unlinked_markers integer;
begin
  if jsonb_typeof(body) is distinct from 'object' then raise sqlstate '22023' using message='Некорректный запрос'; end if;
  a:=fauxlore.current_account();
  if path='my/states' and method='GET' then
    select coalesce(jsonb_agg(item order by item->>'name'),'[]'::jsonb) into result from (
      select jsonb_build_object(
        'id',c.id,'name',c.name,'color',c.color,'is_npc',coalesce(sp.is_npc,true),
        'form_name',sp.government_name,'principles',sp.principles,
        'official_race',(select name from fauxlore.map_categories where layer='races' and id=sp.official_race_id),
        'official_religion',(select name from fauxlore.map_categories where layer='religions' and id=sp.official_religion_id),
        'corruption',coalesce(sp.corruption,0.2),
        'crime',coalesce(sp.crime,0.2),
        'province_count',(select count(*) from fauxlore.province_values v join fauxlore.provinces p on p.id=v.province_id where v.layer='states' and v.category_id=c.id and p.kind='land'),
        'population',(select coalesce(sum(p.population),0) from fauxlore.province_values v join fauxlore.provinces p on p.id=v.province_id where v.layer='states' and v.category_id=c.id and p.kind='land'),
        'taxes',(select coalesce(sum(p.taxes),0) from fauxlore.province_values v join fauxlore.provinces p on p.id=v.province_id where v.layer='states' and v.category_id=c.id and p.kind='land'),
        'provinces',coalesce((select jsonb_agg(jsonb_build_object(
          'id',p.id,'name',p.name,'kind',p.kind,'area',p.area,'province_type',p.province_type,'population',p.population,'development',p.development,
          'belonging',p.belonging,'trade_status',p.trade_status,'control',p.control,'occupation',p.occupation,'taxes',p.taxes,'production',p.production,
          'race',(select rc.name from fauxlore.province_values rv join fauxlore.map_categories rc on rc.layer=rv.layer and rc.id=rv.category_id where rv.province_id=p.id and rv.layer='races'),
          'religion',(select rc.name from fauxlore.province_values rv join fauxlore.map_categories rc on rc.layer=rv.layer and rc.id=rv.category_id where rv.province_id=p.id and rv.layer='religions'),
          'resource',(select rc.name from fauxlore.province_values rv join fauxlore.map_categories rc on rc.layer=rv.layer and rc.id=rv.category_id where rv.province_id=p.id and rv.layer='resources')
        ) order by p.id) from fauxlore.province_values v join fauxlore.provinces p on p.id=v.province_id
        where v.layer='states' and v.category_id=c.id and p.kind='land'),'[]'::jsonb)
      ) as item
      from fauxlore.account_states ast join fauxlore.map_categories c on c.layer='states' and c.id=ast.state_id
      left join fauxlore.state_profiles sp on sp.state_id=c.id where ast.account_id=a.id
    ) owned;
    return result;
  end if;
  if path !~ '^admin/states/[0-9]+$' or method<>'DELETE' then raise sqlstate '22023' using message='Некорректный запрос'; end if;
  if a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
  if body<>'{}'::jsonb then raise sqlstate '22023' using message='Удаление государства не принимает параметры'; end if;
  state_value:=split_part(path,'/',3)::integer; fingerprint:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=game_state_api.request_id;
  if found then
    if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if;
    return previous.result;
  end if;
  select name into state_name from fauxlore.map_categories where layer='states' and id=state_value for update;
  if not found then raise sqlstate 'P0002' using message='Государство не найдено'; end if;
  update fauxlore.map_markers set state_id=null where state_id=state_value; get diagnostics unlinked_markers=row_count;
  delete from fauxlore.province_values where layer='states' and category_id=state_value; get diagnostics removed_assignments=row_count;
  select count(*) into province_count from fauxlore.province_values where layer='states' and category_id=state_value;
  delete from fauxlore.account_states where layer='states' and state_id=state_value;
  delete from fauxlore.state_profiles where state_id=state_value;
  delete from fauxlore.map_categories where layer='states' and id=state_value;
  update fauxlore._settings set value_json=to_jsonb((value_json#>>'{}')::bigint+1) where key='data_revision';
  result:=jsonb_build_object('id',state_value,'name',state_name,'deleted',true,'removed_province_assignments',removed_assignments,'unlinked_markers',unlinked_markers,'remaining_assignments',province_count);
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,game_state_api.request_id,fingerprint,result);
  return result;
end $$;
revoke all on function fauxlore.game_state_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.game_state_api(text,text,jsonb,uuid) to anon,authenticated;

-- State creation rules are also recorded in migrations/20261021114711_state_profiles.sql.
create or replace function fauxlore.government_form(chosen jsonb) returns text
language plpgsql immutable set search_path='' as $$
declare authority text:=chosen->>'authority'; structure text:=chosen->>'structure';
  economy text:=chosen->>'economy'; military text:=chosen->>'military';
  bases text[]; base text; economic text; army text; style integer; gender text;
begin
  if authority is null or authority<>all(array['Династия','Магистрат','Клир','Диктат','Вече']) or
     structure is null or structure<>all(array['Ленное право','Деспотизм','Консорциум','Содружество','Командорство']) or
     economy is null or economy<>all(array['Крепостничество','Гильдии','Адмиралтейство','Корсарство','Работорговля']) or
     military is null or military<>all(array['Сословная армия','Кондотьеры','Фирд','Гвардия','Тумены']) then
    raise sqlstate '22023' using message='Неизвестный принцип государства'; end if;
  if (military='Тумены' and (economy=any(array['Гильдии','Адмиралтейство','Корсарство']) or structure=any(array['Консорциум','Командорство']))) or
     (military='Фирд' and authority=any(array['Династия','Диктат'])) or
     (authority='Клир' and economy='Корсарство') or
     (authority='Вече' and structure='Деспотизм' and economy='Крепостничество') then
    raise sqlstate '22023' using message='Выбранные принципы несовместимы'; end if;
  bases:=case authority
    when 'Династия' then array['Феодальная монархия','Деспотия','Патримониалия','Уния','Марка']
    when 'Магистрат' then array['Республика','Олигархия','Директория','Вольный союз','Подеста']
    when 'Клир' then array['Княжество-епископство','Теократия','Аббатская синьория','Конгрегация','Орден']
    when 'Диктат' then array['Синьория','Тирания','Компания','Протекторат','Стратократия']
    else array['Боярская республика','Революционная диктатура','Коммуна','Кантональный союз','Вольница'] end;
  base:=bases[array_position(array['Ленное право','Деспотизм','Консорциум','Содружество','Командорство'],structure)];
  style:=case when authority=any(array['Магистрат','Вече']) then 1 else 2 end;
  economic:=(case economy
    when 'Крепостничество' then array['Аграрная','Поместная']
    when 'Гильдии' then array['Торговая','Ганзейская']
    when 'Адмиралтейство' then array['Морская','Флотская']
    when 'Корсарство' then array['Пиратская','Каперская']
    else array['Работорговая','Рабовладельческая'] end)[style];
  army:=(case military
    when 'Сословная армия' then array['Шляхетская','Рыцарская']
    when 'Кондотьеры' then array['Вольная','Кондотьерская']
    when 'Фирд' then array['Гражданская','Земская']
    when 'Гвардия' then array['Патрицианская','Гвардейская']
    else array['Степная','Ордынская'] end)[style];
  gender:=case when base='Княжество-епископство' then 'n'
    when base=any(array['Вольный союз','Подеста','Орден','Протекторат','Кантональный союз']) then 'm' else 'f' end;
  if gender='m' then
    army:=regexp_replace(regexp_replace(army,'ская$','ский'),'ая$','ый');
    economic:=regexp_replace(regexp_replace(economic,'ская$','ский'),'ая$','ый');
  elsif gender='n' then
    army:=regexp_replace(regexp_replace(army,'ская$','ское'),'ая$','ое');
    economic:=regexp_replace(regexp_replace(economic,'ская$','ское'),'ая$','ое');
  end if;
  return army||' '||lower(economic)||' '||lower(base);
end $$;
revoke all on function fauxlore.government_form(jsonb) from public,anon,authenticated;

create or replace function fauxlore.state_api(path text, method text, body jsonb, request_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; result jsonb; previous fauxlore.operations; fingerprint text;
  state_name text; state_color text; race_id integer; religion_id integer; state_id integer;
  chosen jsonb; form_name text;
begin
  if path<>'admin/states' or method not in ('GET','POST') or jsonb_typeof(body) is distinct from 'object' then
    raise sqlstate '22023' using message='Некорректный запрос'; end if;
  a:=fauxlore.current_account();
  if a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  if method='GET' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',c.id,'name',c.name,'color',c.color,'is_npc',coalesce(s.is_npc,true),
      'form_name',s.government_name,'principles',s.principles,
      'official_race',r.name,'official_religion',rel.name,
      'corruption',coalesce(s.corruption,0.2),
      'province_count',(select count(*) from fauxlore.province_values v where v.layer='states' and v.category_id=c.id),
      'population',(select coalesce(sum(p.population),0) from fauxlore.province_values v join fauxlore.provinces p on p.id=v.province_id where v.layer='states' and v.category_id=c.id),
      'taxes',(select coalesce(sum(p.taxes),0) from fauxlore.province_values v join fauxlore.provinces p on p.id=v.province_id where v.layer='states' and v.category_id=c.id),
      'players',coalesce((select jsonb_agg(ac.nickname order by ac.nickname) from fauxlore.account_states ast join fauxlore.accounts ac on ac.id=ast.account_id where ast.state_id=c.id),'[]'::jsonb)
    ) order by c.name),'[]'::jsonb) into result
    from fauxlore.map_categories c
    left join fauxlore.state_profiles s on s.state_id=c.id
    left join fauxlore.map_categories r on r.layer='races' and r.id=s.official_race_id
    left join fauxlore.map_categories rel on rel.layer='religions' and rel.id=s.official_religion_id
    where c.layer='states';
    return result;
  end if;
  if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
  fingerprint:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=state_api.request_id;
  if found then
    if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if;
    return previous.result;
  end if;
  if body-array['name','color','authority','structure','economy','military','ephemeral','race_id','religion_id','ruler_name','ruler_surname','ruler_gender','ruler_title','ruler_age']<>'{}' then
    raise sqlstate '22023' using message='Неизвестное поле государства'; end if;
  state_name:=nullif(btrim(body->>'name'),''); state_color:=body->>'color';
  if state_name is null or length(state_name)>100 then raise sqlstate '22023' using message='Укажите название до 100 символов'; end if;
  if state_color is null or state_color!~'^#[0-9a-fA-F]{6}$' then raise sqlstate '22023' using message='Укажите цвет в формате #RRGGBB'; end if;
  if jsonb_typeof(body->'race_id') is distinct from 'number' or jsonb_typeof(body->'religion_id') is distinct from 'number' then
    raise sqlstate '22023' using message='Выберите расу и религию'; end if;
  race_id:=(body->>'race_id')::integer; religion_id:=(body->>'religion_id')::integer;
  if not exists(select 1 from fauxlore.map_categories where layer='races' and id=race_id) or
     not exists(select 1 from fauxlore.map_categories where layer='religions' and id=religion_id) then
    raise sqlstate '22023' using message='Раса или религия не найдена'; end if;
  if length(btrim(coalesce(body->>'ruler_name','')))<2 or length(btrim(coalesce(body->>'ruler_surname','')))<1 or
     body->>'ruler_gender' not in ('Мужской','Женский','Иной') or length(btrim(coalesce(body->>'ruler_title','')))<2 or
     coalesce((body->>'ruler_age')::integer,0)<16 or coalesce((body->>'ruler_age')::integer,0)>250 then
    raise sqlstate '22023' using message='Заполните имя, фамилию, пол, титул и допустимый возраст правителя'; end if;
  if body->>'ephemeral' is null or body->>'ephemeral'<>all(array['Мораторий','Придворные чародеи','Герметизм','Святые Таинства','Артефакторика']) then
    raise sqlstate '22023' using message='Неизвестный эфемерный принцип'; end if;
  chosen:=jsonb_build_object('authority',body->>'authority','structure',body->>'structure',
    'economy',body->>'economy','military',body->>'military','ephemeral',body->>'ephemeral');
  form_name:=fauxlore.government_form(chosen);
  perform pg_advisory_xact_lock(hashtextextended('fauxlore:state-category',0));
  select coalesce(max(id),0)+1 into state_id from fauxlore.map_categories where layer='states';
  insert into fauxlore.map_categories(layer,id,name,color) values('states',state_id,state_name,lower(state_color));
  insert into fauxlore.state_profiles(state_id,principles,government_name,official_race_id,official_religion_id,created_by,
    ruler_name,ruler_surname,ruler_gender,ruler_title,ruler_age)
    values(state_id,chosen,form_name,race_id,religion_id,a.id,btrim(body->>'ruler_name'),btrim(body->>'ruler_surname'),
      body->>'ruler_gender',btrim(body->>'ruler_title'),(body->>'ruler_age')::smallint);
  update fauxlore._settings set value_json=to_jsonb((value_json#>>'{}')::bigint+1) where key='data_revision';
  result:=jsonb_build_object('id',state_id,'name',state_name,'color',lower(state_color),'is_npc',true,
    'form_name',form_name,'principles',chosen,'corruption',0.2,'province_count',0,'population',0,'taxes',0,
    'official_race',(select name from fauxlore.map_categories where layer='races' and id=race_id),
    'official_religion',(select name from fauxlore.map_categories where layer='religions' and id=religion_id),
    'ruler_name',btrim(body->>'ruler_name'),'ruler_surname',btrim(body->>'ruler_surname'),'players','[]'::jsonb);
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,state_api.request_id,fingerprint,result);
  return result;
end $$;
revoke all on function fauxlore.state_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.state_api(text,text,jsonb,uuid) to anon,authenticated;

create or replace function fauxlore.state_emblem_api(path text, method text, body jsonb, request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; state_value integer; image_data text; image_type text; image_bytes bytea;
  result jsonb; previous fauxlore.operations; fingerprint text;
begin
  if jsonb_typeof(body) is distinct from 'object' then raise sqlstate '22023' using message='Некорректный запрос'; end if;
  if method='GET' and path ~ '^state-emblem/[0-9]+$' then
    state_value:=split_part(path,'/',2)::integer;
    if not exists(select 1 from fauxlore.map_categories where layer='states' and id=state_value) then
      raise sqlstate 'P0002' using message='Государство не найдено'; end if;
    select jsonb_build_object('emblem_url',case when sp.emblem_base64 is null then null
      else 'data:'||sp.emblem_type||';base64,'||sp.emblem_base64 end) into result
      from fauxlore.state_profiles sp where sp.state_id=state_value;
    return coalesce(result,jsonb_build_object('emblem_url',null));
  end if;
  if method<>'POST' or path !~ '^admin/state-emblem/[0-9]+$' or not (body ? 'image_data') or body-array['image_data']<>'{}'::jsonb then
    raise sqlstate '22023' using message='Некорректный запрос символики'; end if;
  a:=fauxlore.current_account();
  if a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
  state_value:=split_part(path,'/',3)::integer;
  perform 1 from fauxlore.map_categories where layer='states' and id=state_value for update;
  if not found then raise sqlstate 'P0002' using message='Государство не найдено'; end if;
  image_data:=body->>'image_data'; image_type:=null;
  if image_data is not null then
    if image_data !~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=\r\n]+$' then
      raise sqlstate '22023' using message='Допустимы только JPG, JPEG, PNG или WebP'; end if;
    image_type:=split_part(substr(image_data,6),';',1);
    begin image_bytes:=decode(split_part(image_data,',',2),'base64');
    exception when others then raise sqlstate '22023' using message='Не удалось прочитать файл символики'; end;
    if octet_length(image_bytes)>2097152 then raise sqlstate '22023' using message='Изображение символики должно быть не больше 2 МБ'; end if;
  end if;
  fingerprint:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=state_emblem_api.request_id;
  if found then
    if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if;
    return previous.result;
  end if;
  update fauxlore.state_profiles set emblem_base64=case when image_data is null then null else split_part(image_data,',',2) end,
    emblem_type=image_type where state_id=state_value;
  if not found then raise sqlstate 'P0002' using message='Профиль государства не найден'; end if;
  update fauxlore._settings set value_json=to_jsonb((value_json#>>'{}')::bigint+1) where key='data_revision';
  result:=jsonb_build_object('ok',true,'has_emblem',image_data is not null,'state_id',state_value);
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,state_emblem_api.request_id,fingerprint,result);
  return result;
end $$;
revoke all on function fauxlore.state_emblem_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.state_emblem_api(text,text,jsonb,uuid) to anon,authenticated;

create or replace function public.fauxlore_api(path text, method text default 'GET', body jsonb default '{}', request_id uuid default null)
returns jsonb language sql security invoker set search_path='' as $$
  select case when path ~ '^my/states/[0-9]+/characters$' or path ~ '^admin/states/[0-9]+/characters$' then fauxlore.characters_api(path,method,body,request_id)
    when path='my/applications' and method='GET' then fauxlore.my_applications()
    when path='my/applications' and method='POST' then fauxlore.registration_api_with_surname(path,method,body,request_id)
    when path ~ '^admin/applications/[0-9]+$' and method='PATCH' then fauxlore.registration_api_with_surname(path,method,body,request_id)
    when path like 'my/applications' or path like 'admin/applications%' or path='notifications' or path like 'notifications/%'
      then fauxlore.registration_api(path,method,body,request_id)
    when path ~ '^my/applications/[0-9]+$' then fauxlore.application_details(path,method,body)
    when path ~ '^state-emblem/[0-9]+$' or path ~ '^admin/state-emblem/[0-9]+$' then fauxlore.state_emblem_api(path,method,body,request_id)
    when path='game/calendar' or path='admin/turn/advance' then fauxlore.turn_api(path,method,body,request_id)
    when path='admin/states' then fauxlore.state_api(path,method,body,request_id)
    when path='my/states' or path like 'admin/states/%' then fauxlore.game_state_api(path,method,body,request_id)
    else fauxlore.api(path,method,body,request_id) end
$$;
revoke all on function public.fauxlore_api(text,text,jsonb,uuid) from public;
grant execute on function public.fauxlore_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst, 'reload schema';
create table if not exists fauxlore.state_birth_events (
  id bigint generated always as identity primary key,
  state_id integer not null references fauxlore.state_profiles(state_id) on delete cascade,
  year integer not null,
  turn integer not null,
  father_id bigint not null references fauxlore.state_characters(id),
  mother_id bigint not null references fauxlore.state_characters(id),
  children jsonb not null check(jsonb_typeof(children)='array' and jsonb_array_length(children) between 1 and 3),
  named_at timestamptz,
  created_at timestamptz not null default now(),
  unique(state_id,year)
);
create index if not exists state_birth_events_pending_idx on fauxlore.state_birth_events(state_id,year) where named_at is null;

create table if not exists fauxlore.state_marriage_candidates (
  id bigint generated always as identity primary key,
  state_id integer not null references fauxlore.state_profiles(state_id) on delete cascade,
  created_turn integer not null,
  name text not null,
  surname text not null default '',
  gender text not null check(gender in ('Мужской','Женский')),
  age smallint not null check(age between 18 and 59),
  race_id integer not null,
  religion_id integer not null,
  supported_by text[] not null default '{}',
  selected_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists state_marriage_candidates_current_idx on fauxlore.state_marriage_candidates(state_id,created_turn) where selected_at is null;
alter table fauxlore.state_birth_events enable row level security;
alter table fauxlore.state_marriage_candidates enable row level security;
revoke all on fauxlore.state_birth_events,fauxlore.state_marriage_candidates from public,anon,authenticated;

create or replace function fauxlore.process_annual_births()
returns trigger language plpgsql security definer set search_path='' as $$
declare couple record; child_count integer; child_race integer; children_value jsonb; mother_death_chance numeric; mother_died boolean;
  child_index integer; is_lawful boolean; father_race text; mother_race text; authority_name text; birth_roll numeric;
begin
  if new.year=old.year then return new; end if;
  for couple in
    select sp.state_id,sp.principles,sp.official_race_id,sp.official_religion_id,
      ruler.id ruler_id,ruler.name ruler_name,ruler.surname ruler_surname,ruler.gender ruler_gender,ruler.age ruler_age,
      ruler.race_id ruler_race_id,ruler.religion_id ruler_religion_id,
      spouse.id spouse_id,spouse.gender spouse_gender,spouse.age spouse_age,spouse.race_id spouse_race_id,
      spouse.religion_id spouse_religion_id,
      case when m.character_a_id=ruler.id then m.lawful_for_a else m.lawful_for_b end lawful_for_ruler,
      coalesce(ruler_race.name,'') ruler_race,coalesce(spouse_race.name,'') spouse_race
    from fauxlore.state_profiles sp
    join fauxlore.state_characters ruler on ruler.state_id=sp.state_id and ruler.is_current_ruler and ruler.alive
    join fauxlore.state_marriages m on m.ended_at_turn is null and ruler.id in (m.character_a_id,m.character_b_id)
    join fauxlore.state_characters spouse on spouse.id=case when m.character_a_id=ruler.id then m.character_b_id else m.character_a_id end and spouse.alive
    left join fauxlore.map_categories ruler_race on ruler_race.layer='races' and ruler_race.id=ruler.race_id
    left join fauxlore.map_categories spouse_race on spouse_race.layer='races' and spouse_race.id=spouse.race_id
    where (ruler.gender='Мужской' and ruler.age<60 and spouse.gender='Женский' and spouse.age<45)
       or (ruler.gender='Женский' and ruler.age<45 and spouse.gender='Мужской' and spouse.age<60)
  loop
    father_race:=case when couple.ruler_gender='Мужской' then couple.ruler_race else couple.spouse_race end;
    mother_race:=case when couple.ruler_gender='Женский' then couple.ruler_race else couple.spouse_race end;
    if father_race=mother_race and father_race in ('Люди','Эльфы','Дварфы','Зверолюди') then
      child_race:=case when couple.ruler_gender='Мужской' then couple.ruler_race_id else couple.spouse_race_id end;
    elsif father_race in ('Люди','Эльфы','Полуэльфы') and mother_race in ('Люди','Эльфы','Полуэльфы') then
      child_race:=case when father_race='Люди' and mother_race='Люди' then (select id from fauxlore.map_categories where layer='races' and name='Люди' limit 1)
        when father_race='Эльфы' and mother_race='Эльфы' then (select id from fauxlore.map_categories where layer='races' and name='Эльфы' limit 1)
        else (select id from fauxlore.map_categories where layer='races' and name='Полуэльфы' limit 1) end;
    else continue;
    end if;
    if child_race is null or random()>=.25 then continue; end if;
    birth_roll:=random();
    child_count:=case when birth_roll<.94 then 1 when birth_roll<.99 then 2 else 3 end;
    authority_name:=coalesce(couple.principles->>'authority','');
    is_lawful:=authority_name='Династия' and couple.lawful_for_ruler;
    children_value:='[]'::jsonb;
    for child_index in 1..child_count loop
      children_value:=children_value||jsonb_build_array(jsonb_build_object(
        'gender',case when random()<.5 then 'Мужской' else 'Женский' end,
        'race_id',child_race,
        'religion_id',case when random()<.5 then case when couple.ruler_gender='Мужской' then couple.ruler_religion_id else couple.spouse_religion_id end
          else case when couple.ruler_gender='Женский' then couple.ruler_religion_id else couple.spouse_religion_id end end,
        'legitimacy',case when authority_name='Династия' then case when is_lawful then 'Законный' else 'Незаконный' end else 'Неприменимо' end));
    end loop;
    mother_died:=false;
    mother_death_chance:=case when (case when couple.ruler_gender='Женский' then couple.ruler_age else couple.spouse_age end)<35 then .01
      when (case when couple.ruler_gender='Женский' then couple.ruler_age else couple.spouse_age end)<40 then .03 else .07 end
      +case when child_count=2 then .02 when child_count=3 then .04 else 0 end;
    mother_death_chance:=least(.10,mother_death_chance);
    mother_died:=random()<mother_death_chance;
    insert into fauxlore.state_birth_events(state_id,year,turn,father_id,mother_id,children)
    values(couple.state_id,new.year,new.turn,
      case when couple.ruler_gender='Мужской' then couple.ruler_id else couple.spouse_id end,
      case when couple.ruler_gender='Женский' then couple.ruler_id else couple.spouse_id end,children_value);
    if mother_died then
      update fauxlore.state_characters set alive=false,died_at_turn=new.turn,is_current_ruler=false
      where id=case when couple.ruler_gender='Женский' then couple.ruler_id else couple.spouse_id end;
    end if;
    insert into fauxlore.notifications(account_id,kind,title,message)
    select recipients.account_id,'birth','Рождение в семье правителя',
      'В семье государства родилось детей: '||child_count||'. Откройте вкладку «Власть и династия», чтобы указать имена.'||
      case when mother_died then ' Мать детей умерла при родах.' else '' end
    from (select distinct ast.account_id from fauxlore.account_states ast where ast.layer='states' and ast.state_id=couple.state_id
      union select ac.id from fauxlore.accounts ac where ac.role='admin' and not exists(select 1 from fauxlore.account_states ast where ast.layer='states' and ast.state_id=couple.state_id)) recipients;
  end loop;
  return new;
end $$;
revoke all on function fauxlore.process_annual_births() from public,anon,authenticated;
drop trigger if exists game_calendar_process_births on fauxlore.game_calendar;
create trigger game_calendar_process_births after update of year on fauxlore.game_calendar
for each row when (new.year is distinct from old.year) execute function fauxlore.process_annual_births();

create or replace function fauxlore.character_lifecycle_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; state_value integer; birth_value bigint; candidate_value bigint; state_row fauxlore.state_profiles;
  ruler fauxlore.state_characters; event_row fauxlore.state_birth_events; calendar_row fauxlore.game_calendar;
  result jsonb; fingerprint text; previous fauxlore.operations; names_value jsonb; child jsonb; candidate fauxlore.state_marriage_candidates; spouse_row fauxlore.state_characters;
  gender_value text; race_values integer[]; candidate_names text[]; candidate_surnames text[]; candidate_religion integer;
  candidate_race integer; candidate_age integer; support_value text[]; i integer; ruler_race_name text; authority_name text;
begin
  a:=fauxlore.current_account();
  if path !~ '^my/states/[0-9]+/(birth-events|birth-events/[0-9]+/name|marriage-candidates|marriages/local)$' then
    raise sqlstate '22023' using message='Некорректный запрос'; end if;
  state_value:=split_part(path,'/',3)::integer;
  if not exists(select 1 from fauxlore.account_states ast where ast.account_id=a.id and ast.layer='states' and ast.state_id=state_value) then
    raise sqlstate '42501' using message='Нет доступа к этому государству'; end if;
  select * into state_row from fauxlore.state_profiles where state_id=state_value;
  if not found then raise sqlstate 'P0002' using message='Государство не найдено'; end if;
  if path ~ '/birth-events/[0-9]+/name$' and method='POST' then
    birth_value:=split_part(path,'/',5)::bigint;
    if body-'names'<>'{}'::jsonb or jsonb_typeof(body->'names') is distinct from 'array' then raise sqlstate '22023' using message='Передайте список имён'; end if;
    if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
    fingerprint:=md5(jsonb_build_array(method,path,body)::text);
    perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
    select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=character_lifecycle_api.request_id;
    if found then if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if; return previous.result; end if;
    select * into event_row from fauxlore.state_birth_events where id=birth_value and state_id=state_value for update;
    if not found or event_row.named_at is not null then raise sqlstate 'P0002' using message='Событие рождения уже обработано или не найдено'; end if;
    names_value:=body->'names';
    if jsonb_array_length(names_value)<>jsonb_array_length(event_row.children) or exists(select 1 from jsonb_array_elements_text(names_value) x where length(btrim(x)) not between 1 and 120) then
      raise sqlstate '22023' using message='Укажите имя длиной от 1 до 120 символов для каждого ребёнка'; end if;
    for i in 0..jsonb_array_length(event_row.children)-1 loop
      child:=event_row.children->i;
      insert into fauxlore.state_characters(state_id,name,surname,gender,age,race_id,religion_id,legitimacy,father_id,mother_id)
      values(state_value,btrim(names_value->>i),coalesce((select surname from fauxlore.state_characters where id=event_row.father_id),''),
        child->>'gender',0,(child->>'race_id')::integer,(child->>'religion_id')::integer,child->>'legitimacy',event_row.father_id,event_row.mother_id);
    end loop;
    update fauxlore.state_birth_events set named_at=now() where id=birth_value;
    result:=jsonb_build_object('named',jsonb_array_length(names_value),'birth_id',birth_value);
    insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,character_lifecycle_api.request_id,fingerprint,result);
    return result;
  elsif path='my/states/'||state_value||'/birth-events' and method='GET' and body='{}'::jsonb then
    select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'year',e.year,'turn',e.turn,'children',e.children) order by e.year,e.id),'[]'::jsonb)
      into result from fauxlore.state_birth_events e where e.state_id=state_value and e.named_at is null;
    return result;
  elsif path='my/states/'||state_value||'/marriage-candidates' and method='GET' and body='{}'::jsonb then
    select * into ruler from fauxlore.state_characters where state_id=state_value and is_current_ruler and alive;
    if not found then return jsonb_build_object('candidates','[]'::jsonb,'message','Сейчас в государстве нет действующего правителя.'); end if;
    if exists(select 1 from fauxlore.state_marriages where ended_at_turn is null and ruler.id in(character_a_id,character_b_id)) then
      return jsonb_build_object('candidates','[]'::jsonb,'message','У правителя уже есть супруг.'); end if;
    if state_row.prestige<10 then return jsonb_build_object('candidates','[]'::jsonb,'message','Для местного брака требуется 10 ОП.'); end if;
    select * into calendar_row from fauxlore.game_calendar where singleton=true;
    perform pg_advisory_xact_lock(hashtextextended('marriage-candidates:'||state_value::text,0));
    if not exists(select 1 from fauxlore.state_marriage_candidates where state_id=state_value and created_turn=calendar_row.turn and selected_at is null) then
      gender_value:=case when ruler.gender='Мужской' then 'Женский' else 'Мужской' end;
      select name into ruler_race_name from fauxlore.map_categories where layer='races' and id=ruler.race_id;
      race_values:=array(select id from fauxlore.map_categories where layer='races' and name=any(
        case ruler_race_name when 'Люди' then array['Люди','Эльфы','Полуэльфы'] when 'Эльфы' then array['Люди','Эльфы','Полуэльфы']
          when 'Полуэльфы' then array['Люди','Эльфы','Полуэльфы'] when 'Дварфы' then array['Дварфы'] when 'Зверолюди' then array['Зверолюди'] else array[ruler_race_name] end));
      candidate_names:=case when gender_value='Женский' then array['Алиса','Велена','Дарья','Елена','Ирина','Лада','Мира','Надежда','Рада','Ярослава'] else array['Алексей','Борис','Владимир','Глеб','Дамир','Илья','Мирослав','Ратибор','Святослав','Яромир'] end;
      candidate_surnames:=array['Белоярский','Ветров','Зорин','Каменев','Лесной','Руднев','Серебряков','Сумеречный'];
      authority_name:=coalesce(state_row.principles->>'authority','');
      support_value:=case authority_name when 'Династия' then array['Корона','Знать'] when 'Магистрат' then array['Духовенство','Горожане']
        when 'Клир' then array['Духовенство'] when 'Диктат' then array['Корона'] when 'Вече' then array['Горожане','Крестьяне','Духовенство']
        else array['Корона','Знать','Духовенство','Горожане','Крестьяне'] end;
      for i in 1..3 loop
        candidate_race:=race_values[1+floor(random()*cardinality(race_values))::integer];
        select id into candidate_religion from fauxlore.map_categories where layer='religions' order by random() limit 1;
        candidate_age:=case when gender_value='Женский' then 18+floor(random()*27)::integer else 18+floor(random()*42)::integer end;
        insert into fauxlore.state_marriage_candidates(state_id,created_turn,name,surname,gender,age,race_id,religion_id,supported_by)
        values(state_value,calendar_row.turn,candidate_names[1+floor(random()*cardinality(candidate_names))::integer],candidate_surnames[1+floor(random()*cardinality(candidate_surnames))::integer],gender_value,candidate_age,candidate_race,candidate_religion,
          case when random()<.34 then array[support_value[1+floor(random()*cardinality(support_value))::integer]] else '{}'::text[] end);
      end loop;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'surname',c.surname,'gender',c.gender,'age',c.age,
      'race',(select name from fauxlore.map_categories where layer='races' and id=c.race_id),
      'religion',(select name from fauxlore.map_categories where layer='religions' and id=c.religion_id),'supported_by',c.supported_by) order by c.id),'[]'::jsonb)
      into result from fauxlore.state_marriage_candidates c where c.state_id=state_value and c.created_turn=calendar_row.turn and c.selected_at is null;
    return jsonb_build_object('candidates',result,'message','Выберите кандидата. Заключение местного брака стоит 10 ОП.');
  elsif path='my/states/'||state_value||'/marriages/local' and method='POST' then
    if body-'candidate_id'<>'{}'::jsonb or coalesce(body->>'candidate_id','') !~ '^\d+$' then raise sqlstate '22023' using message='Некорректный кандидат'; end if;
    if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
    fingerprint:=md5(jsonb_build_array(method,path,body)::text);
    perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
    select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=character_lifecycle_api.request_id;
    if found then if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if; return previous.result; end if;
    select * into ruler from fauxlore.state_characters where state_id=state_value and is_current_ruler and alive for update;
    select * into calendar_row from fauxlore.game_calendar where singleton=true;
    select * into candidate from fauxlore.state_marriage_candidates where id=(body->>'candidate_id')::bigint and state_id=state_value and created_turn=calendar_row.turn and selected_at is null for update;
    if not found then raise sqlstate 'P0002' using message='Кандидат устарел. Обновите список.'; end if;
    if ruler.id is null then raise sqlstate 'P0002' using message='Нет действующего правителя'; end if;
    if exists(select 1 from fauxlore.state_marriages where ended_at_turn is null and ruler.id in(character_a_id,character_b_id)) then raise sqlstate '22023' using message='У правителя уже есть супруг'; end if;
    if state_row.prestige<10 then raise sqlstate '22023' using message='Для местного брака требуется 10 ОП'; end if;
    authority_name:=coalesce(state_row.principles->>'authority','');
    select * into state_row from fauxlore.state_profiles where state_id=state_value for update;
    if state_row.prestige<10 then raise sqlstate '22023' using message='Для местного брака требуется 10 ОП'; end if;
    insert into fauxlore.state_characters(state_id,name,surname,gender,age,race_id,religion_id,legitimacy)
    values(state_value,candidate.name,candidate.surname,candidate.gender,candidate.age,candidate.race_id,candidate.religion_id,'Неприменимо') returning * into spouse_row;
    insert into fauxlore.state_marriages(character_a_id,character_b_id,marriage_type,lawful_for_a,lawful_for_b,started_at_turn)
    values(ruler.id,spouse_row.id,'local',authority_name='Династия',authority_name='Династия',calendar_row.turn);
    update fauxlore.state_marriage_candidates set selected_at=now() where id=(body->>'candidate_id')::bigint;
    update fauxlore.state_profiles set prestige=prestige-10 where state_id=state_value;
    result:=jsonb_build_object('married',true,'spouse_id',spouse_row.id,'cost',10);
    insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,character_lifecycle_api.request_id,fingerprint,result);
    insert into fauxlore.notifications(account_id,kind,title,message) values(a.id,'marriage','Заключён местный брак','Правитель заключил местный брак. Потрачено 10 ОП.');
    return result;
  end if;
  raise sqlstate '22023' using message='Недопустимый запрос';
end $$;
revoke all on function fauxlore.character_lifecycle_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.character_lifecycle_api(text,text,jsonb,uuid) to authenticated;

create or replace function public.fauxlore_api(path text,method text default 'GET',body jsonb default '{}',request_id uuid default null)
returns jsonb language sql security invoker set search_path='' as $$
  select case
    when path ~ '^my/states/[0-9]+/(birth-events|birth-events/[0-9]+/name|marriage-candidates|marriages/local)$'
      then fauxlore.character_lifecycle_api(path,method,body,request_id)
    when path ~ '^my/states/[0-9]+/characters$' or path ~ '^admin/states/[0-9]+/characters$'
      then fauxlore.characters_api(path,method,body,request_id)
    when path='my/applications' and method='GET' then fauxlore.my_applications()
    when path='my/applications' and method='POST' then fauxlore.registration_api_with_surname(path,method,body,request_id)
    when path ~ '^admin/applications/[0-9]+$' and method='PATCH' then fauxlore.registration_api_with_surname(path,method,body,request_id)
    when path like 'my/applications' or path like 'admin/applications%' or path='notifications' or path like 'notifications/%'
      then fauxlore.registration_api(path,method,body,request_id)
    when path ~ '^my/applications/[0-9]+$' then fauxlore.application_details(path,method,body)
    when path ~ '^state-emblem/[0-9]+$' or path ~ '^admin/state-emblem/[0-9]+$' then fauxlore.state_emblem_api(path,method,body,request_id)
    when path='game/calendar' or path='admin/turn/advance' then fauxlore.turn_api(path,method,body,request_id)
    when path='admin/states' then fauxlore.state_api(path,method,body,request_id)
    when path='my/states' or path like 'admin/states/%' then fauxlore.game_state_api(path,method,body,request_id)
    else fauxlore.api(path,method,body,request_id)
  end
$$;
revoke all on function public.fauxlore_api(text,text,jsonb,uuid) from public;
grant execute on function public.fauxlore_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst,'reload schema';

-- Lightweight revision endpoint and statement-level invalidation for background refresh.
insert into fauxlore._settings(key,value_json) values('live_revision','1'::jsonb) on conflict(key) do nothing;
create or replace function fauxlore.bump_live_revision()
returns trigger language plpgsql security definer set search_path='' as $$
begin
  update fauxlore._settings set value_json=to_jsonb(coalesce((value_json#>>'{}')::bigint,0)+1) where key='live_revision';
  return null;
end $$;
revoke all on function fauxlore.bump_live_revision() from public,anon,authenticated;
create or replace function fauxlore.map_revision()
returns jsonb language sql stable security definer set search_path='' as $$
  select jsonb_build_object(
    'data_revision',coalesce((select (value_json#>>'{}')::bigint from fauxlore._settings where key='data_revision'),0),
    'live_revision',coalesce((select (value_json#>>'{}')::bigint from fauxlore._settings where key='live_revision'),0),
    'tile_revision',coalesce((select value_json#>>'{}' from fauxlore._settings where key='tile_revision'),'')
  )
$$;
revoke all on function fauxlore.map_revision() from public,anon,authenticated;
grant execute on function fauxlore.map_revision() to anon,authenticated;
-- Attach triggers after every private table has been created.
do $$ declare item record; begin
  for item in select tablename from pg_tables where schemaname='fauxlore' and (
    tablename like 'state\_%' escape '\' or tablename like 'map\_%' escape '\'
    or tablename in ('provinces','province_values','account_states','game_calendar','economy_parameters'))
  loop
    execute format('drop trigger if exists fauxlore_live_revision on fauxlore.%I',item.tablename);
    execute format('create trigger fauxlore_live_revision after insert or update or delete on fauxlore.%I for each statement execute function fauxlore.bump_live_revision()',item.tablename);
  end loop;
end $$;
create or replace function public.fauxlore_api(path text,method text default 'GET',body jsonb default '{}',request_id uuid default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
begin
  if path='map/revision' and method='GET' then return fauxlore.map_revision();
  elsif path in ('economy/config','admin/economy/config') then return fauxlore.economy_config_api(path,method,body,request_id);
  elsif path ~ '^my/states/[0-9]+/(birth-events|birth-events/[0-9]+/name|marriage-candidates|marriages/local)$' then return fauxlore.character_lifecycle_api(path,method,body,request_id);
  elsif path ~ '^my/states/[0-9]+/characters$' or path ~ '^admin/states/[0-9]+/characters$' then return fauxlore.characters_api(path,method,body,request_id);
  elsif path='my/marriage-offers' or path ~ '^(my|admin)/marriage-offers/[0-9]+/(accept|reject)$' then return fauxlore.dynastic_marriage_api(path,method,body,request_id);
  elsif path ~ '^(my|admin)/states/[0-9]+/abdicate$' then return fauxlore.abdicate_api(path,method,body,request_id);
  elsif path ~ '^(my|admin)/states/[0-9]+/(succession(/events/[0-9]+/choose)?|politics|designate)$' then return fauxlore.succession_api(path,method,body,request_id);
  elsif path='my/applications' and method='GET' then return fauxlore.my_applications();
  elsif path='my/applications' and method='POST' then return fauxlore.registration_api_with_surname(path,method,body,request_id);
  elsif path ~ '^admin/applications/[0-9]+$' and method='PATCH' then return fauxlore.registration_api_with_surname(path,method,body,request_id);
  elsif path='my/applications' or path like 'admin/applications%' or path='notifications' or path like 'notifications/%' then return fauxlore.registration_api(path,method,body,request_id);
  elsif path ~ '^my/applications/[0-9]+$' then return fauxlore.application_details(path,method,body);
  elsif path ~ '^state-emblem/[0-9]+$' or path ~ '^admin/state-emblem/[0-9]+$' then return fauxlore.state_emblem_api(path,method,body,request_id);
  elsif path='game/calendar' or path='admin/turn/advance' then return fauxlore.turn_api(path,method,body,request_id);
  elsif path='admin/states' then return fauxlore.state_api(path,method,body,request_id);
  elsif path='my/states' or path like 'admin/states/%' then return fauxlore.game_state_api(path,method,body,request_id);
  else return fauxlore.api(path,method,body,request_id);
  end if;
end;
$$;
revoke all on function public.fauxlore_api(text,text,jsonb,uuid) from public;
grant execute on function public.fauxlore_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst,'reload schema';

-- Expose only the compact revision token through a dedicated public RPC.
create or replace function public.map_revision_api()
returns jsonb language sql stable security invoker set search_path='' as $$
  select fauxlore.map_revision()
$$;
revoke all on function public.map_revision_api() from public;
grant execute on function public.map_revision_api() to anon,authenticated;
notify pgrst,'reload schema';

-- Stage 4: calculate provincial taxes from authoritative database values,
-- split receipts between the Crown and the estate, and credit state treasuries.

update fauxlore.economy_parameters
set config=config||jsonb_build_object('estateTaxGreed',jsonb_build_object(
  'Господствующее|Корона',0,'Господствующее|Знать',0.60,'Господствующее|Духовенство',0.50,'Господствующее|Горожане',0.50,'Господствующее|Крестьяне',0.40,
  'Ключевое|Корона',0,'Ключевое|Знать',0.35,'Ключевое|Духовенство',0.30,'Ключевое|Горожане',0.30,'Ключевое|Крестьяне',0.20,
  'Значимое|Корона',0,'Значимое|Знать',0.20,'Значимое|Духовенство',0.15,'Значимое|Горожане',0.15,'Значимое|Крестьяне',0.10,
  'Бесправное|Корона',0,'Бесправное|Знать',0.05,'Бесправное|Духовенство',0.05,'Бесправное|Горожане',0.05,'Бесправное|Крестьяне',0
)) where singleton=true;

create table if not exists fauxlore.state_treasuries (
  state_id integer not null references fauxlore.state_profiles(state_id) on delete cascade,
  estate text not null check(estate in ('Корона','Знать','Духовенство','Горожане','Крестьяне')),
  balance numeric(14,2) not null default 0 check(balance>=0),
  updated_at timestamptz not null default now(),
  primary key(state_id,estate)
);
alter table fauxlore.state_treasuries enable row level security;
revoke all on fauxlore.state_treasuries from public,anon,authenticated;

create or replace function fauxlore.initialize_state_treasuries()
returns trigger language plpgsql security definer set search_path='' as $$
begin
  insert into fauxlore.state_treasuries(state_id,estate,balance) values
    (new.state_id,'Корона',15000),(new.state_id,'Знать',3000),(new.state_id,'Духовенство',3000),
    (new.state_id,'Горожане',3000),(new.state_id,'Крестьяне',3000)
  on conflict(state_id,estate) do nothing;
  update fauxlore.state_profiles set treasury=(select coalesce(sum(balance),0) from fauxlore.state_treasuries where state_id=new.state_id)
  where state_id=new.state_id;
  return new;
end $$;
revoke all on function fauxlore.initialize_state_treasuries() from public,anon,authenticated;
drop trigger if exists state_profiles_initialize_treasuries on fauxlore.state_profiles;
create trigger state_profiles_initialize_treasuries after insert on fauxlore.state_profiles
for each row execute function fauxlore.initialize_state_treasuries();

-- Existing states receive the same agreed starting balances as newly approved states.
insert into fauxlore.state_treasuries(state_id,estate,balance)
select s.state_id,e.estate,e.balance
from fauxlore.state_profiles s
cross join (values ('Корона',15000::numeric),('Знать',3000::numeric),('Духовенство',3000::numeric),('Горожане',3000::numeric),('Крестьяне',3000::numeric)) e(estate,balance)
on conflict(state_id,estate) do nothing;
update fauxlore.state_profiles s set treasury=t.total
from (select state_id,sum(balance)::numeric(14,2) total from fauxlore.state_treasuries group by state_id) t
where t.state_id=s.state_id;

create or replace function fauxlore.split_province_tax(gross numeric,belonging text,status text,cfg jsonb)
returns table(crown numeric,estate numeric) language plpgsql immutable set search_path='' as $$
declare greed numeric;
begin
  if gross is null or gross<0 then raise sqlstate '22023' using message='Сумма налога не может быть отрицательной'; end if;
  if belonging is null or belonging='Отсутствует' then return query select round(gross,2),0::numeric; return; end if;
  if belonging not in ('Корона','Знать','Духовенство','Горожане','Крестьяне') or status not in ('Господствующее','Ключевое','Значимое','Бесправное') then
    raise sqlstate '22023' using message='Неизвестное сословие или его статус';
  end if;
  greed:=nullif(cfg#>>array['estateTaxGreed',status||'|'||belonging],'')::numeric;
  if greed is null or greed<0 or greed>1 then raise sqlstate '22023' using message='Не задан корректный коэффициент распределения налога'; end if;
  return query select round(gross*(1-greed),2),gross-round(gross*(1-greed),2);
end $$;
revoke all on function fauxlore.split_province_tax(numeric,text,text,jsonb) from public,anon,authenticated;

create or replace function fauxlore.turn_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; calendar_row fauxlore.game_calendar; previous fauxlore.operations;
  fingerprint text; result jsonb; cfg jsonb; tax_rows jsonb; state_rows jsonb; states_count integer:=0;
  province_row record; tax_gross numeric; crown_tax numeric; estate_tax numeric; status_value text;
  beneficiary_id integer; beneficiary_name text; tax_share numeric; expected_year integer; expected_turn integer;
  report_value jsonb:='[]'::jsonb;
begin
  if path='game/calendar' and method='GET' then
    select * into calendar_row from fauxlore.game_calendar where singleton=true;
    return jsonb_build_object('year',calendar_row.year,'turn',calendar_row.turn);
  end if;
  if path<>'admin/turn/advance' or method<>'POST' or jsonb_typeof(body) is distinct from 'object' or
    body-array['expected_year','expected_turn','report']<>'{}' or
    jsonb_typeof(body->'expected_year') is distinct from 'number' or jsonb_typeof(body->'expected_turn') is distinct from 'number' then
    raise sqlstate '22023' using message='Некорректный запрос смены хода';
  end if;
  if (body->>'expected_year')!~'^\d+$' or (body->>'expected_turn')!~'^\d+$' then
    raise sqlstate '22023' using message='Ожидаемые год и ход должны быть целыми числами';
  end if;
  if body ? 'report' and (jsonb_typeof(body->'report') is distinct from 'array' or octet_length((body->'report')::text)>1500000) then
    raise sqlstate '22023' using message='Некорректный запрос смены хода';
  end if;
  expected_year:=(body->>'expected_year')::integer; expected_turn:=(body->>'expected_turn')::integer;
  a:=fauxlore.current_account();
  if a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
  fingerprint:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into previous from fauxlore.operations o where o.account_id=a.id and o.request_id=turn_api.request_id;
  if found then
    if previous.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if;
    return previous.result;
  end if;
  select * into calendar_row from fauxlore.game_calendar where singleton=true for update;
  if calendar_row.year<>expected_year or calendar_row.turn<>expected_turn then
    raise sqlstate '40001' using message='Ход уже изменён в другой сессии. Обновите страницу и повторите.';
  end if;
  select config into cfg from fauxlore.economy_parameters where singleton=true for share;

  create temporary table if not exists pg_temp.turn_tax_lines(
    province_id integer, province_name text, recipient_id integer, recipient_name text,
    belonging text, gross numeric, crown numeric, estate numeric
  ) on commit drop;
  truncate pg_temp.turn_tax_lines;
  for province_row in
    select p.id,p.name,p.population,p.province_type,p.control,p.occupation,
      race.name race_name,religion.name religion_name,owner.id owner_id,owner.name owner_name,
      occupier.id occupier_id,occupier.name occupier_name,
      p.belonging
    from fauxlore.provinces p
    left join fauxlore.province_values rv on rv.province_id=p.id and rv.layer='races'
    left join fauxlore.map_categories race on race.layer='races' and race.id=rv.category_id
    left join fauxlore.province_values relv on relv.province_id=p.id and relv.layer='religions'
    left join fauxlore.map_categories religion on religion.layer='religions' and religion.id=relv.category_id
    left join fauxlore.province_values ov on ov.province_id=p.id and ov.layer='states'
    left join fauxlore.map_categories owner on owner.layer='states' and owner.id=ov.category_id
    left join fauxlore.map_categories occupier on occupier.layer='states' and lower(occupier.name)=lower(p.occupation)
    where p.kind='land' and (ov.category_id is not null or p.occupation is not null)
    order by p.id
  loop
    if province_row.occupation is not null and (province_row.owner_id is null or lower(province_row.occupation)<>lower(province_row.owner_name)) then
      beneficiary_id:=province_row.occupier_id; beneficiary_name:=province_row.occupier_name; tax_share:=.5;
      if beneficiary_id is null then raise sqlstate '22023' using message='Не найдено государство-оккупант провинции '||province_row.id; end if;
    else
      beneficiary_id:=province_row.owner_id; beneficiary_name:=province_row.owner_name; tax_share:=1;
    end if;
    if beneficiary_id is null then continue; end if;
    if province_row.race_name is null or province_row.religion_name is null then
      raise sqlstate '22023' using message='Для провинции '||province_row.id||' не заданы раса или религия'; end if;
    if nullif(cfg#>>array['provinceModifiers',province_row.province_type,'tax'],'') is null or
       nullif(cfg#>>array['raceTaxRates',province_row.race_name],'') is null or
       nullif(cfg#>>array['religionTaxRates',province_row.religion_name],'') is null then
      raise sqlstate '22023' using message='Не заданы налоговые коэффициенты провинции '||province_row.id; end if;
    if coalesce(province_row.control,100)<0 or coalesce(province_row.control,100)>100 then
      raise sqlstate '22023' using message='Контроль провинции должен быть от 0 до 100'; end if;
    tax_gross:=round(greatest(0,province_row.population)::numeric/10 *
      ((cfg#>>array['raceTaxRates',province_row.race_name])::numeric+(cfg#>>array['religionTaxRates',province_row.religion_name])::numeric) *
      (cfg#>>array['provinceModifiers',province_row.province_type,'tax'])::numeric *
      coalesce(province_row.control,100)::numeric/100 * tax_share,2);
    beneficiary_id:=case when province_row.occupation is not null and tax_share=.5 then province_row.occupier_id else province_row.owner_id end;
    if beneficiary_id is null then continue; end if;
    if province_row.belonging is null or province_row.belonging='Отсутствует' then
      select crown,estate into crown_tax,estate_tax from fauxlore.split_province_tax(tax_gross,'Отсутствует',null,cfg);
    else
      status_value:=fauxlore.estate_status_for(beneficiary_id,province_row.belonging);
      select crown,estate into crown_tax,estate_tax from fauxlore.split_province_tax(tax_gross,province_row.belonging,status_value,cfg);
    end if;
    insert into pg_temp.turn_tax_lines values(province_row.id,province_row.name,beneficiary_id,beneficiary_name,
      coalesce(province_row.belonging,'Отсутствует'),tax_gross,crown_tax,estate_tax);
  end loop;

  with receipts as (
    select recipient_id,'Корона'::text estate,sum(crown)::numeric(14,2) amount from pg_temp.turn_tax_lines group by recipient_id
    union all
    select recipient_id,belonging,sum(estate)::numeric(14,2) from pg_temp.turn_tax_lines where belonging<>'Отсутствует' group by recipient_id,belonging
  )
  insert into fauxlore.state_treasuries(state_id,estate,balance)
  select recipient_id,estate,amount from receipts where amount<>0
  on conflict(state_id,estate) do update set balance=fauxlore.state_treasuries.balance+excluded.balance,updated_at=now();
  update fauxlore.state_profiles sp set treasury=(select coalesce(sum(st.balance),0) from fauxlore.state_treasuries st where st.state_id=sp.state_id)
  where exists(select 1 from pg_temp.turn_tax_lines l where l.recipient_id=sp.state_id);

  select coalesce(jsonb_agg(state_report order by state_report->>'name'),'[]'::jsonb),count(*)::integer
    into report_value,states_count
  from (
    select jsonb_build_object(
      'id',s.recipient_id,'name',s.recipient_name,
      'province_count',count(distinct l.province_id),
      'gross_taxes',round(coalesce(sum(l.gross),0),2),
      'crown_taxes',round(coalesce(sum(l.crown),0),2),
      'estate_taxes',round(coalesce(sum(l.estate),0),2),
      'tax_buckets',coalesce((select jsonb_object_agg(st.estate,round(st.balance,2)) from fauxlore.state_treasuries st where st.state_id=s.id),'{}'::jsonb),
      'opening_treasury',round(coalesce((select sum(st.balance) from fauxlore.state_treasuries st where st.state_id=s.id),0)-coalesce(sum(l.crown+l.estate),0),2),
      'closing_treasury',round(coalesce((select sum(st.balance) from fauxlore.state_treasuries st where st.state_id=s.id),0),2),
      'tax_details',coalesce(jsonb_agg(jsonb_build_object('province_id',l.province_id,'province_name',l.province_name,
        'belonging',l.belonging,'gross',l.gross,'crown',l.crown,'estate',l.estate) order by l.province_id)
        filter(where l.province_id is not null),'[]'::jsonb)
    ) state_report
    from (select distinct recipient_id,recipient_name from pg_temp.turn_tax_lines) s
    left join pg_temp.turn_tax_lines l on l.recipient_id=s.recipient_id
    group by s.recipient_id,s.recipient_name
  ) reports;
  insert into fauxlore.turn_economy_reports(year,turn,report,created_by)
    values(calendar_row.year,calendar_row.turn,report_value,a.id);

  -- Keep the established annual character lifecycle within this same atomic turn.
  for province_row in
    select ch.id,ch.state_id,ch.age,ch.name,ch.surname,ch.is_current_ruler,coalesce(rc.name,'') race_name
    from fauxlore.state_characters ch left join fauxlore.map_categories rc on rc.layer='races' and rc.id=ch.race_id
    where ch.alive order by ch.id for update of ch
  loop
    declare age_value integer; death_chance numeric; died boolean;
    begin
      age_value:=least(250,province_row.age+1);
      death_chance:=case
        when province_row.race_name in ('Люди','Полуэльфы','Зверолюди') then case when age_value<60 then 0 when age_value<=70 then .05 when age_value<=80 then .15 when age_value<=90 then .25 when age_value<=100 then .50 else .70 end
        when province_row.race_name='Дварфы' then case when age_value<80 then 0 when age_value<=90 then .05 when age_value<=100 then .15 when age_value<=110 then .25 when age_value<=120 then .50 else .70 end
        when province_row.race_name='Эльфы' then case when age_value<100 then 0 when age_value<=120 then .05 when age_value<=140 then .15 when age_value<=160 then .25 when age_value<=180 then .50 else .70 end
        else 0 end;
      died:=death_chance>0 and random()<death_chance;
      update fauxlore.state_characters set age=age_value,alive=not died,
        died_at_turn=case when died then calendar_row.turn else died_at_turn end,
        is_current_ruler=case when died and province_row.is_current_ruler then false else is_current_ruler end where id=province_row.id;
      if died and province_row.is_current_ruler then
        insert into fauxlore.notifications(account_id,kind,title,message)
        select recipients.account_id,'ruler_death','Умер правитель государства',
          'Правитель '||trim(province_row.name||' '||province_row.surname)||' умер в возрасте '||age_value||' лет. Требуется провести передачу власти.'
        from (
          select distinct ast.account_id from fauxlore.account_states ast where ast.layer='states' and ast.state_id=province_row.state_id
          union
          select ac.id from fauxlore.accounts ac where ac.role='admin'
            and not exists(select 1 from fauxlore.account_states ast where ast.layer='states' and ast.state_id=province_row.state_id)
        ) recipients;
      end if;
    end;
  end loop;
  update fauxlore.game_calendar set year=year+1,turn=turn+1,updated_at=now() where singleton=true returning * into calendar_row;
  result:=jsonb_build_object('year',calendar_row.year,'turn',calendar_row.turn,
    'calculated_year',calendar_row.year-1,'calculated_turn',calendar_row.turn-1,'states_calculated',states_count);
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,turn_api.request_id,fingerprint,result);
  return result;
end $$;
revoke all on function fauxlore.turn_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.turn_api(text,text,jsonb,uuid) to anon,authenticated;

create or replace function fauxlore.economy_config_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; old_config jsonb; next_config jsonb; prior fauxlore.operations; fp text; item jsonb; pair record; key_name text; result jsonb;
begin
  if path='economy/config' and method='GET' then return (select config from fauxlore.economy_parameters where singleton=true); end if;
  if path not in ('admin/economy/config','economy/config') then raise sqlstate 'P0002' using message='Метод API не найден'; end if;
  a:=fauxlore.current_account();
  if a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  select config into old_config from fauxlore.economy_parameters where singleton=true for update;
  if path='admin/economy/config' and method='GET' then return old_config; end if;
  if path<>'admin/economy/config' or method<>'PATCH' or request_id is null or body-'config'<>'{}' or jsonb_typeof(body->'config') is distinct from 'object' then
    raise sqlstate '22023' using message='Некорректное изменение параметров экономики'; end if;
  fp:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into prior from fauxlore.operations where account_id=a.id and fauxlore.operations.request_id=economy_config_api.request_id;
  if found then if prior.fingerprint<>fp then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if; return prior.result; end if;
  next_config:=body->'config';
  if (select array_agg(k order by k) from jsonb_object_keys(next_config) k)<>
     (select array_agg(k order by k) from jsonb_object_keys(old_config) k) or next_config->'occupationMultiplier'<>'0.5'::jsonb then
    raise sqlstate '22023' using message='Набор параметров или коэффициент оккупации изменён'; end if;
  foreach key_name in array array['raceTaxRates','religionTaxRates','tradeStatusModifiers','raceGrowthModifiers','recruitGrowthModifiers','recruitLimitModifiers','estateRecruitModifiers','provinceValueWeights','estateTaxGreed'] loop
    if (select array_agg(k order by k) from jsonb_object_keys(next_config->key_name) k)<>
       (select array_agg(k order by k) from jsonb_object_keys(old_config->key_name) k) then raise sqlstate '22023' using message='Изменён состав справочника коэффициентов'; end if;
    for pair in select key,value from jsonb_each(next_config->key_name) loop
      if jsonb_typeof(pair.value)<>'number' or (pair.value#>>'{}')::numeric<0 or
        (pair.value#>>'{}')::numeric>(case when key_name='estateTaxGreed' then 1 else 10000 end) then
        raise sqlstate '22023' using message='Коэффициент должен быть числом в допустимом диапазоне'; end if;
    end loop;
  end loop;
  if jsonb_typeof(next_config->'taxLoyaltySensitivity')<>'number' or (next_config->>'taxLoyaltySensitivity')::numeric<0 or (next_config->>'taxLoyaltySensitivity')::numeric>5 then
    raise sqlstate '22023' using message='Чувствительность лояльности должна быть от 0 до 5'; end if;
  if (select array_agg(k order by k) from jsonb_object_keys(next_config->'provinceModifiers') k)<>
     (select array_agg(k order by k) from jsonb_object_keys(old_config->'provinceModifiers') k) then raise sqlstate '22023' using message='Изменён состав типов провинций'; end if;
  for pair in select key,value from jsonb_each(next_config->'provinceModifiers') loop
    if (select array_agg(k order by k) from jsonb_object_keys(pair.value) k)<>
       (select array_agg(k order by k) from jsonb_object_keys(old_config->'provinceModifiers'->pair.key) k) then raise sqlstate '22023' using message='Изменён состав модификатора типа'; end if;
    for key_name in select k from jsonb_object_keys(pair.value) k loop
      if jsonb_typeof(pair.value->key_name)<>'number' or (pair.value->>key_name)::numeric<0 or (pair.value->>key_name)::numeric>10000 then raise sqlstate '22023' using message='Модификатор должен быть числом от 0 до 10000'; end if;
    end loop;
  end loop;
  if jsonb_typeof(next_config->'resources')<>'array' or jsonb_array_length(next_config->'resources')<>jsonb_array_length(old_config->'resources') then raise sqlstate '22023' using message='Изменён состав ресурсов'; end if;
  for item in select value from jsonb_array_elements(next_config->'resources') loop
    if not exists(select 1 from jsonb_array_elements(old_config->'resources') old where old->>'name'=item->>'name' and old->'category'=item->'category' and old->'showInProduction'=item->'showInProduction') then raise sqlstate '22023' using message='Изменены сведения о ресурсе'; end if;
    foreach key_name in array array['value','production','consumption'] loop
      if jsonb_typeof(item->key_name)<>'number' or (item->>key_name)::numeric<0 or (item->>key_name)::numeric>1000000 then raise sqlstate '22023' using message='Параметр ресурса должен быть числом от 0 до 1000000'; end if;
    end loop;
  end loop;
  insert into fauxlore.economy_parameter_history(account_id,before_config,after_config) values(a.id,old_config,next_config);
  update fauxlore.economy_parameters set config=next_config,updated_at=now() where singleton=true;
  result:=jsonb_build_object('config',next_config);
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,request_id,fp,result);
  return result;
end $$;
revoke all on function fauxlore.economy_config_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.economy_config_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst,'reload schema';

-- Stage 5: configurable army upkeep, treasury shortfall tracking, and auditable cash movements.

create table if not exists fauxlore.army_unit_types (
  id bigint generated always as identity primary key,
  name text not null unique check(length(btrim(name)) between 1 and 80),
  upkeep_per_unit numeric(14,2) not null default 0 check(upkeep_per_unit>=0),
  updated_by bigint references fauxlore.accounts(id),
  updated_at timestamptz not null default now()
);
create table if not exists fauxlore.state_army_units (
  state_id integer not null references fauxlore.state_profiles(state_id) on delete cascade,
  unit_type_id bigint not null references fauxlore.army_unit_types(id),
  quantity integer not null check(quantity>=0),
  primary key(state_id,unit_type_id)
);
create table if not exists fauxlore.state_treasury_debts (
  state_id integer primary key references fauxlore.state_profiles(state_id) on delete cascade,
  balance numeric(14,2) not null default 0 check(balance>=0),
  updated_at timestamptz not null default now()
);
create table if not exists fauxlore.state_budget_ledger (
  id bigint generated always as identity primary key,
  state_id integer not null references fauxlore.state_profiles(state_id) on delete cascade,
  estate text not null check(estate='Корона'),
  year integer not null,
  turn integer not null,
  kind text not null check(kind in ('army_upkeep','debt_repayment')),
  unit_type_id bigint references fauxlore.army_unit_types(id) on delete set null,
  cash_delta numeric(14,2) not null,
  debt_delta numeric(14,2) not null,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique(state_id,year,turn,kind,unit_type_id)
);
alter table fauxlore.army_unit_types enable row level security;
alter table fauxlore.state_army_units enable row level security;
alter table fauxlore.state_treasury_debts enable row level security;
alter table fauxlore.state_budget_ledger enable row level security;
revoke all on fauxlore.army_unit_types,fauxlore.state_army_units,fauxlore.state_treasury_debts,fauxlore.state_budget_ledger from public,anon,authenticated;
insert into fauxlore.state_treasury_debts(state_id) select state_id from fauxlore.state_profiles on conflict do nothing;

-- Keep this initializer in sync so approved/new states get a debt row as well.
create or replace function fauxlore.initialize_state_treasuries()
returns trigger language plpgsql security definer set search_path='' as $$
begin
  insert into fauxlore.state_treasuries(state_id,estate,balance) values
    (new.state_id,'Корона',15000),(new.state_id,'Знать',3000),(new.state_id,'Духовенство',3000),
    (new.state_id,'Горожане',3000),(new.state_id,'Крестьяне',3000)
  on conflict(state_id,estate) do nothing;
  insert into fauxlore.state_treasury_debts(state_id) values(new.state_id) on conflict(state_id) do nothing;
  update fauxlore.state_profiles set treasury=(select coalesce(sum(balance),0) from fauxlore.state_treasuries where state_id=new.state_id)
  where state_id=new.state_id;
  return new;
end $$;
revoke all on function fauxlore.initialize_state_treasuries() from public,anon,authenticated;

create or replace function fauxlore.army_budget_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; state_value integer; prior fauxlore.operations; fingerprint text;
  result jsonb; item jsonb; unit_name text; quantity_value integer; unit_type_id_value bigint; rate_value numeric;
begin
  if path !~ '^admin/states/[0-9]+/army$' or method not in ('GET','PATCH') or jsonb_typeof(body) is distinct from 'object' then
    raise sqlstate '22023' using message='Некорректный запрос состава армии';
  end if;
  a:=fauxlore.current_account();
  if a.role<>'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  state_value:=split_part(path,'/',3)::integer;
  if not exists(select 1 from fauxlore.state_profiles where state_id=state_value) then raise sqlstate 'P0002' using message='Государство не найдено'; end if;
  if method='GET' then
    select jsonb_build_object('state_id',state_value,'state_name',c.name,
      'treasury',(select balance from fauxlore.state_treasuries where state_id=state_value and estate='Корона'),
      'debt',(select coalesce(balance,0) from fauxlore.state_treasury_debts where state_id=state_value),
      'units',coalesce((select jsonb_agg(jsonb_build_object('name',t.name,'quantity',u.quantity,'upkeep_per_unit',t.upkeep_per_unit) order by t.name)
        from fauxlore.state_army_units u join fauxlore.army_unit_types t on t.id=u.unit_type_id where u.state_id=state_value),'[]'::jsonb))
      into result from fauxlore.map_categories c where c.layer='states' and c.id=state_value;
    return result;
  end if;
  if request_id is null or body-array['units']<>'{}' or jsonb_typeof(body->'units') is distinct from 'array' or jsonb_array_length(body->'units')>100 then
    raise sqlstate '22023' using message='Передайте до 100 типов частей';
  end if;
  if exists(select 1 from jsonb_array_elements(body->'units') e(value)
      where jsonb_typeof(value) is distinct from 'object' or value-array['name','quantity','upkeep_per_unit']<>'{}'
        or jsonb_typeof(value->'name') is distinct from 'string' or jsonb_typeof(value->'quantity') is distinct from 'number'
        or jsonb_typeof(value->'upkeep_per_unit') is distinct from 'number'
        or length(btrim(value->>'name')) not between 1 and 80 or (value->>'quantity')!~'^\d+$'
        or (value->>'quantity')::numeric>1000000 or (value->>'upkeep_per_unit')::numeric<0 or (value->>'upkeep_per_unit')::numeric>1000000) then
    raise sqlstate '22023' using message='Проверьте название, количество и содержание частей';
  end if;
  if exists(select lower(value->>'name') from jsonb_array_elements(body->'units') e(value) group by lower(value->>'name') having count(*)>1) then
    raise sqlstate '22023' using message='Типы частей не должны повторяться';
  end if;
  if coalesce((select sum((value->>'quantity')::numeric*(value->>'upkeep_per_unit')::numeric)
      from jsonb_array_elements(body->'units') e(value)),0)>999999999999.99 then
    raise sqlstate '22023' using message='Общая стоимость армии превышает допустимый предел';
  end if;
  fingerprint:=md5(jsonb_build_array(method,path,body)::text);
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into prior from fauxlore.operations o where o.account_id=a.id and o.request_id=army_budget_api.request_id;
  if found then
    if prior.fingerprint<>fingerprint then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if;
    return prior.result;
  end if;
  perform 1 from fauxlore.state_profiles where state_id=state_value for update;
  delete from fauxlore.state_army_units where state_id=state_value;
  for item in select value from jsonb_array_elements(body->'units') loop
    unit_name:=btrim(item->>'name'); quantity_value:=(item->>'quantity')::integer; rate_value:=(item->>'upkeep_per_unit')::numeric;
    insert into fauxlore.army_unit_types(name,upkeep_per_unit,updated_by,updated_at)
      values(unit_name,rate_value,a.id,now())
      on conflict(name) do update set upkeep_per_unit=excluded.upkeep_per_unit,updated_by=excluded.updated_by,updated_at=now()
      returning id into unit_type_id_value;
    if (item->>'quantity')::integer>0 then
      insert into fauxlore.state_army_units(state_id,unit_type_id,quantity) values(state_value,unit_type_id_value,(item->>'quantity')::integer);
    end if;
  end loop;
  select jsonb_build_object('state_id',state_value,'state_name',c.name,
      'treasury',(select balance from fauxlore.state_treasuries where state_id=state_value and estate='Корона'),
      'debt',(select coalesce(balance,0) from fauxlore.state_treasury_debts where state_id=state_value),
      'units',coalesce((select jsonb_agg(jsonb_build_object('name',t.name,'quantity',u.quantity,'upkeep_per_unit',t.upkeep_per_unit) order by t.name)
        from fauxlore.state_army_units u join fauxlore.army_unit_types t on t.id=u.unit_type_id where u.state_id=state_value),'[]'::jsonb))
    into result from fauxlore.map_categories c where c.layer='states' and c.id=state_value;
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,request_id,fingerprint,result);
  return result;
end $$;
revoke all on function fauxlore.army_budget_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.army_budget_api(text,text,jsonb,uuid) to anon,authenticated;

create or replace function fauxlore.charge_army_upkeep_before_turn()
returns trigger language plpgsql security definer set search_path='' as $$
declare report_value jsonb; report_item jsonb; report_name text; report_array jsonb; state_row record; unit_row record;
  crown_balance numeric; debt_balance numeric; debt_paid numeric; expense_total numeric; expense_paid numeric;
  available numeric; line_cost numeric; line_paid numeric; remaining_cost numeric; remaining_cash numeric;
  unpaid numeric; new_treasury numeric; details jsonb; item_index integer; item_count integer;
begin
  if new.year=old.year and new.turn=old.turn then return new; end if;
  select report into report_value from fauxlore.turn_economy_reports where year=old.year and turn=old.turn for update;
  if report_value is null then raise sqlstate '22023' using message='Не найден налоговый отчёт для расчётного хода'; end if;
  for state_row in
    select u.state_id,c.name state_name,round(sum(u.quantity*t.upkeep_per_unit),2) expense_total,
      jsonb_agg(jsonb_build_object('unit_type_id',t.id,'name',t.name,'quantity',u.quantity,'upkeep_per_unit',t.upkeep_per_unit,
        'cost',round(u.quantity*t.upkeep_per_unit,2)) order by t.name) units
    from fauxlore.state_army_units u join fauxlore.army_unit_types t on t.id=u.unit_type_id
    join fauxlore.map_categories c on c.layer='states' and c.id=u.state_id
    where u.quantity>0 group by u.state_id,c.name having sum(u.quantity*t.upkeep_per_unit)>0
    union
    select d.state_id,c.name,0::numeric,'[]'::jsonb
    from fauxlore.state_treasury_debts d join fauxlore.map_categories c on c.layer='states' and c.id=d.state_id
    where d.balance>0 and not exists(select 1 from fauxlore.state_army_units u join fauxlore.army_unit_types t on t.id=u.unit_type_id
      where u.state_id=d.state_id and u.quantity>0 and t.upkeep_per_unit>0)
    order by 1
  loop
    insert into fauxlore.state_treasury_debts(state_id) values(state_row.state_id) on conflict(state_id) do nothing;
    select balance into crown_balance from fauxlore.state_treasuries where state_id=state_row.state_id and estate='Корона' for update;
    select balance into debt_balance from fauxlore.state_treasury_debts where state_id=state_row.state_id for update;
    debt_paid:=least(crown_balance,debt_balance);
    if debt_paid>0 then
      update fauxlore.state_treasuries set balance=balance-debt_paid,updated_at=now() where state_id=state_row.state_id and estate='Корона';
      update fauxlore.state_treasury_debts set balance=balance-debt_paid,updated_at=now() where state_id=state_row.state_id;
      insert into fauxlore.state_budget_ledger(state_id,estate,year,turn,kind,cash_delta,debt_delta,details)
        values(state_row.state_id,'Корона',old.year,old.turn,'debt_repayment',-debt_paid,-debt_paid,jsonb_build_object('amount',debt_paid));
      crown_balance:=crown_balance-debt_paid; debt_balance:=debt_balance-debt_paid;
    end if;
    expense_total:=state_row.expense_total; available:=crown_balance;
    remaining_cost:=expense_total; remaining_cash:=least(available,expense_total);
    select count(*) into item_count from jsonb_array_elements(state_row.units);
    details:='[]'::jsonb; item_index:=0;
    for unit_row in select value from jsonb_array_elements(state_row.units) e(value) loop
      item_index:=item_index+1; line_cost:=(unit_row.value->>'cost')::numeric;
      if expense_total<=available then line_paid:=line_cost;
      elsif item_index=item_count then line_paid:=remaining_cash;
      else line_paid:=least(line_cost,round(remaining_cash*line_cost/remaining_cost,2)); end if;
      line_paid:=least(line_cost,line_paid,remaining_cash);
      unpaid:=line_cost-line_paid; remaining_cash:=remaining_cash-line_paid; remaining_cost:=remaining_cost-line_cost;
      details:=details||jsonb_build_array(unit_row.value||jsonb_build_object('paid',line_paid,'arrears',unpaid));
      insert into fauxlore.state_budget_ledger(state_id,estate,year,turn,kind,unit_type_id,cash_delta,debt_delta,details)
        values(state_row.state_id,'Корона',old.year,old.turn,'army_upkeep',(unit_row.value->>'unit_type_id')::bigint,-line_paid,unpaid,
          unit_row.value||jsonb_build_object('paid',line_paid,'arrears',unpaid));
    end loop;
    expense_paid:=least(available,expense_total); unpaid:=expense_total-expense_paid;
    if expense_paid>0 then update fauxlore.state_treasuries set balance=balance-expense_paid,updated_at=now() where state_id=state_row.state_id and estate='Корона'; end if;
    if unpaid>0 then update fauxlore.state_treasury_debts set balance=balance+unpaid,updated_at=now() where state_id=state_row.state_id; end if;
    update fauxlore.state_profiles sp set treasury=(select coalesce(sum(st.balance),0) from fauxlore.state_treasuries st where st.state_id=sp.state_id)
      where sp.state_id=state_row.state_id;
    select coalesce(sum(balance),0) into new_treasury from fauxlore.state_treasuries where state_id=state_row.state_id;
    select coalesce(balance,0) into debt_balance from fauxlore.state_treasury_debts where state_id=state_row.state_id;
    report_name:=state_row.state_name;
    report_item:=jsonb_build_object('id',state_row.state_id,'name',report_name,'province_count',0,'gross_taxes',0,'crown_taxes',0,
      'estate_taxes',0,'tax_buckets',jsonb_build_object('Корона',crown_balance),'tax_details','[]'::jsonb);
    if exists(select 1 from jsonb_array_elements(report_value) x(value) where (value->>'id')::integer=state_row.state_id) then
      select value into report_item from jsonb_array_elements(report_value) x(value) where (value->>'id')::integer=state_row.state_id limit 1;
      report_array:=(select coalesce(jsonb_agg(case when (value->>'id')::integer=state_row.state_id then
        value||jsonb_build_object('tax_buckets',coalesce(value->'tax_buckets','{}'::jsonb)||jsonb_build_object('Корона',crown_balance),
          'army_upkeep',expense_total,'army_upkeep_paid',expense_paid,'army_upkeep_arrears',unpaid,'debt_repaid',debt_paid,
          'treasury_debt',debt_balance,'closing_treasury',new_treasury,'army_details',details)
        else value end order by ord),'[]'::jsonb) from jsonb_array_elements(report_value) with ordinality x(value,ord));
    else
      report_array:=report_value||jsonb_build_array(report_item||jsonb_build_object('army_upkeep',expense_total,'army_upkeep_paid',expense_paid,
        'army_upkeep_arrears',unpaid,'debt_repaid',debt_paid,'treasury_debt',debt_balance,'closing_treasury',new_treasury,'army_details',details));
    end if;
    report_value:=report_array;
  end loop;
  update fauxlore.turn_economy_reports set report=report_value where year=old.year and turn=old.turn;
  return new;
end $$;
revoke all on function fauxlore.charge_army_upkeep_before_turn() from public,anon,authenticated;
drop trigger if exists game_calendar_charge_army_upkeep on fauxlore.game_calendar;
create trigger game_calendar_charge_army_upkeep before update of year,turn on fauxlore.game_calendar
for each row execute function fauxlore.charge_army_upkeep_before_turn();

create or replace function public.fauxlore_api(path text,method text default 'GET',body jsonb default '{}',request_id uuid default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
begin
  if path='map/revision' and method='GET' then return fauxlore.map_revision();
  elsif path ~ '^my/states/[0-9]+/(birth-events|birth-events/[0-9]+/name|marriage-candidates|marriages/local)$' then return fauxlore.character_lifecycle_api(path,method,body,request_id);
  elsif path ~ '^my/states/[0-9]+/characters$' or path ~ '^admin/states/[0-9]+/characters$' then return fauxlore.characters_api(path,method,body,request_id);
  elsif path='my/marriage-offers' or path ~ '^(my|admin)/marriage-offers/[0-9]+/(accept|reject)$' then return fauxlore.dynastic_marriage_api(path,method,body,request_id);
  elsif path ~ '^(my|admin)/states/[0-9]+/abdicate$' then return fauxlore.abdicate_api(path,method,body,request_id);
  elsif path ~ '^(my|admin)/states/[0-9]+/(succession(/events/[0-9]+/choose)?|politics|designate)$' then return fauxlore.succession_api(path,method,body,request_id);
  elsif path='my/applications' and method='GET' then return fauxlore.my_applications();
  elsif path='my/applications' and method='POST' then return fauxlore.registration_api_with_surname(path,method,body,request_id);
  elsif path ~ '^admin/applications/[0-9]+$' and method='PATCH' then return fauxlore.registration_api_with_surname(path,method,body,request_id);
  elsif path='my/applications' or path like 'admin/applications%' or path='notifications' or path like 'notifications/%' then return fauxlore.registration_api(path,method,body,request_id);
  elsif path ~ '^my/applications/[0-9]+$' then return fauxlore.application_details(path,method,body);
  elsif path ~ '^state-emblem/[0-9]+$' or path ~ '^admin/state-emblem/[0-9]+$' then return fauxlore.state_emblem_api(path,method,body,request_id);
  elsif path ~ '^admin/states/[0-9]+/army$' then return fauxlore.army_budget_api(path,method,body,request_id);
  elsif path='game/calendar' or path='admin/turn/advance' then return fauxlore.turn_api(path,method,body,request_id);
  elsif path='admin/states' then return fauxlore.state_api(path,method,body,request_id);
  elsif path='my/states' or path like 'admin/states/%' then return fauxlore.game_state_api(path,method,body,request_id);
  else return fauxlore.api(path,method,body,request_id); end if;
end $$;
revoke all on function public.fauxlore_api(text,text,jsonb,uuid) from public;
grant execute on function public.fauxlore_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst,'reload schema';

-- Add an administrator-only read API for the last committed turn budget report.
create or replace function fauxlore.turn_budget_report_api(path text,method text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; result jsonb;
begin
  if path<>'admin/turn/latest-report' or method<>'GET' then raise sqlstate 'P0002' using message='Метод API не найден'; end if;
  a:=fauxlore.current_account();
  if a.role is distinct from 'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  select jsonb_build_object('year',r.year,'turn',r.turn,'states',r.report) into result
  from fauxlore.turn_economy_reports r order by r.year desc,r.turn desc limit 1;
  return coalesce(result,jsonb_build_object('year',null,'turn',null,'states','[]'::jsonb));
end $$;
revoke all on function fauxlore.turn_budget_report_api(text,text) from public,anon,authenticated;
grant execute on function fauxlore.turn_budget_report_api(text,text) to authenticated;

create or replace function public.fauxlore_api(path text,method text default 'GET',body jsonb default '{}',request_id uuid default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
begin
  if path='map/revision' and method='GET' then return fauxlore.map_revision();
  elsif path ~ '^my/states/[0-9]+/(birth-events|birth-events/[0-9]+/name|marriage-candidates|marriages/local)$' then return fauxlore.character_lifecycle_api(path,method,body,request_id);
  elsif path ~ '^my/states/[0-9]+/characters$' or path ~ '^admin/states/[0-9]+/characters$' then return fauxlore.characters_api(path,method,body,request_id);
  elsif path='my/marriage-offers' or path ~ '^(my|admin)/marriage-offers/[0-9]+/(accept|reject)$' then return fauxlore.dynastic_marriage_api(path,method,body,request_id);
  elsif path ~ '^(my|admin)/states/[0-9]+/abdicate$' then return fauxlore.abdicate_api(path,method,body,request_id);
  elsif path ~ '^(my|admin)/states/[0-9]+/(succession(/events/[0-9]+/choose)?|politics|designate)$' then return fauxlore.succession_api(path,method,body,request_id);
  elsif path='my/applications' and method='GET' then return fauxlore.my_applications();
  elsif path='my/applications' and method='POST' then return fauxlore.registration_api_with_surname(path,method,body,request_id);
  elsif path ~ '^admin/applications/[0-9]+$' and method='PATCH' then return fauxlore.registration_api_with_surname(path,method,body,request_id);
  elsif path='my/applications' or path like 'admin/applications%' or path='notifications' or path like 'notifications/%' then return fauxlore.registration_api(path,method,body,request_id);
  elsif path ~ '^my/applications/[0-9]+$' then return fauxlore.application_details(path,method,body);
  elsif path ~ '^state-emblem/[0-9]+$' or path ~ '^admin/state-emblem/[0-9]+$' then return fauxlore.state_emblem_api(path,method,body,request_id);
  elsif path ~ '^admin/states/[0-9]+/army$' then return fauxlore.army_budget_api(path,method,body,request_id);
  elsif path='admin/turn/latest-report' then return fauxlore.turn_budget_report_api(path,method);
  elsif path='game/calendar' or path='admin/turn/advance' then return fauxlore.turn_api(path,method,body,request_id);
  elsif path='admin/states' then return fauxlore.state_api(path,method,body,request_id);
  elsif path='my/states' or path like 'admin/states/%' then return fauxlore.game_state_api(path,method,body,request_id);
  else return fauxlore.api(path,method,body,request_id); end if;
end $$;
revoke all on function public.fauxlore_api(text,text,jsonb,uuid) from public;
grant execute on function public.fauxlore_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst,'reload schema';

-- Cover foreign keys used by admin attribution and per-type budget history.
create index if not exists army_unit_types_updated_by_idx on fauxlore.army_unit_types(updated_by);
create index if not exists state_army_units_unit_type_idx on fauxlore.state_army_units(unit_type_id);
create index if not exists state_budget_ledger_unit_type_idx on fauxlore.state_budget_ledger(unit_type_id);
-- Player-adjustable race/religion tax rates, an administrator treasury view,
-- and a guarded test-turn checkpoint that can be rolled back safely.

create table if not exists fauxlore.state_tax_rates (
  state_id integer not null references fauxlore.state_profiles(state_id) on delete cascade,
  layer text not null check(layer in ('races','religions')),
  category_id integer not null,
  rate numeric(8,4) not null check(rate>=0 and rate<=100),
  changed_year integer not null,
  changed_turn integer not null,
  changed_by bigint not null references fauxlore.accounts(id),
  updated_at timestamptz not null default now(),
  primary key(state_id,layer,category_id),
  foreign key(layer,category_id) references fauxlore.map_categories(layer,id)
);
alter table fauxlore.state_tax_rates enable row level security;
revoke all on fauxlore.state_tax_rates from public,anon,authenticated;
create index if not exists state_tax_rates_layer_category_idx on fauxlore.state_tax_rates(layer,category_id);
drop trigger if exists fauxlore_live_revision on fauxlore.state_tax_rates;
create trigger fauxlore_live_revision after insert or update or delete on fauxlore.state_tax_rates
for each statement execute function fauxlore.bump_live_revision();

create table if not exists fauxlore.turn_test_snapshot (
  singleton boolean primary key default true check(singleton),
  payload jsonb not null,
  before_year integer not null,
  before_turn integer not null,
  after_year integer,
  after_turn integer,
  after_revision bigint,
  actor_id bigint not null references fauxlore.accounts(id),
  advance_request_id uuid not null,
  created_at timestamptz not null default now()
);
alter table fauxlore.turn_test_snapshot enable row level security;
revoke all on fauxlore.turn_test_snapshot from public,anon,authenticated;

create or replace function fauxlore.effective_state_tax_rate(state_key integer,layer_key text,category_key integer,fallback_config jsonb)
returns numeric language sql stable security definer set search_path='' as $$
  select coalesce(
    (select r.rate from fauxlore.state_tax_rates r where r.state_id=state_key and r.layer=layer_key and r.category_id=category_key),
    nullif(fallback_config#>>array[case layer_key when 'races' then 'raceTaxRates' else 'religionTaxRates' end,
      (select c.name from fauxlore.map_categories c where c.layer=layer_key and c.id=category_key)],'')::numeric
  )
$$;
revoke all on function fauxlore.effective_state_tax_rate(integer,text,integer,jsonb) from public,anon,authenticated;

-- Patch the installed Stage 4 function without copying its long annual lifecycle logic.
do $$
declare fn text; old_fragment text; new_fragment text;
begin
  fn:=replace(pg_get_functiondef('fauxlore.turn_api(text,text,jsonb,uuid)'::regprocedure),chr(13),'');
  if position('fauxlore.effective_state_tax_rate' in fn)>0 then return; end if;
  fn:=replace(fn,'beneficiary_id integer; beneficiary_name text; tax_share numeric; expected_year integer; expected_turn integer;',
    'beneficiary_id integer; beneficiary_name text; tax_share numeric; expected_year integer; expected_turn integer; race_rate numeric; religion_rate numeric;');
  fn:=replace(fn,'race.name race_name,religion.name religion_name,owner.id owner_id,owner.name owner_name,',
    'race.name race_name,rv.category_id race_id,religion.name religion_name,relv.category_id religion_id,owner.id owner_id,owner.name owner_name,');
  old_fragment:='if nullif(cfg#>>array[''provinceModifiers'',province_row.province_type,''tax''],'''') is null or'||chr(10)||
       '       nullif(cfg#>>array[''raceTaxRates'',province_row.race_name],'''') is null or'||chr(10)||
       '       nullif(cfg#>>array[''religionTaxRates'',province_row.religion_name],'''') is null then'||chr(10)||
       '      raise sqlstate ''22023'' using message=''Не заданы налоговые коэффициенты провинции ''||province_row.id; end if;';
  new_fragment:='race_rate:=fauxlore.effective_state_tax_rate(beneficiary_id,''races'',province_row.race_id,cfg);'||chr(10)||
       '    religion_rate:=fauxlore.effective_state_tax_rate(beneficiary_id,''religions'',province_row.religion_id,cfg);'||chr(10)||
       '    if nullif(cfg#>>array[''provinceModifiers'',province_row.province_type,''tax''],'''') is null or race_rate is null or religion_rate is null then'||chr(10)||
       '      raise sqlstate ''22023'' using message=''Не заданы налоговые коэффициенты провинции ''||province_row.id; end if;';
  if position(old_fragment in fn)=0 then raise exception 'Could not locate the Stage 4 tax validation fragment'; end if;
  fn:=replace(fn,old_fragment,new_fragment);
  old_fragment:='((cfg#>>array[''raceTaxRates'',province_row.race_name])::numeric+(cfg#>>array[''religionTaxRates'',province_row.religion_name])::numeric) *';
  if position(old_fragment in fn)=0 then raise exception 'Could not locate the Stage 4 tax calculation fragment'; end if;
  fn:=replace(fn,old_fragment,'(race_rate+religion_rate) *');
  execute fn;
end $$;

create or replace function fauxlore.state_tax_rates_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; state_key integer; state_name text; calendar_row fauxlore.game_calendar; cfg jsonb;
  layer_key text; category_key integer; rate_value numeric; category_name text; prior fauxlore.operations;
  fp text; result jsonb; existing fauxlore.state_tax_rates; is_admin boolean;
begin
  a:=fauxlore.current_account(); is_admin:=a.role='admin';
  if path='admin/economy/treasuries' and method='GET' then
    if not is_admin then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
    return coalesce((select jsonb_agg(jsonb_build_object('id',s.state_id,'name',c.name,'treasury',s.treasury,'prestige',s.prestige,
      'debt',coalesce(d.balance,0),'players',coalesce((select jsonb_agg(ac.nickname order by ac.nickname) from fauxlore.account_states ast join fauxlore.accounts ac on ac.id=ast.account_id where ast.layer='states' and ast.state_id=s.state_id and ac.role<>'admin'),'[]'::jsonb),
      'buckets',coalesce((select jsonb_object_agg(t.estate,t.balance order by t.estate) from fauxlore.state_treasuries t where t.state_id=s.state_id),'{}'::jsonb)) order by c.name)
      from fauxlore.state_profiles s join fauxlore.map_categories c on c.layer='states' and c.id=s.state_id
      left join fauxlore.state_treasury_debts d on d.state_id=s.state_id),'[]'::jsonb);
  end if;
  if path !~ '^(my|admin)/states/[0-9]+/tax-rates$' then raise sqlstate 'P0002' using message='Метод API не найден'; end if;
  if (path like 'admin/%') is distinct from is_admin then raise sqlstate '42501' using message='Недостаточно прав'; end if;
  state_key:=substring(path from '[0-9]+')::integer;
  if not exists(select 1 from fauxlore.state_profiles where state_id=state_key) then raise sqlstate 'P0002' using message='Государство не найдено'; end if;
  if not is_admin and not exists(select 1 from fauxlore.account_states ast where ast.account_id=a.id and ast.layer='states' and ast.state_id=state_key) then
    raise sqlstate '42501' using message='Это государство не закреплено за вашим аккаунтом'; end if;
  select * into calendar_row from fauxlore.game_calendar where singleton=true;
  select config into cfg from fauxlore.economy_parameters where singleton=true;
  select c.name into state_name from fauxlore.map_categories c where c.layer='states' and c.id=state_key;
  if method='GET' then
    return jsonb_build_object('state_id',state_key,'state_name',state_name,'year',calendar_row.year,'turn',calendar_row.turn,
      'prestige',(select prestige from fauxlore.state_profiles where state_id=state_key),
      'treasury',(select treasury from fauxlore.state_profiles where state_id=state_key),
      'debt',coalesce((select balance from fauxlore.state_treasury_debts where state_id=state_key),0),
      'buckets',coalesce((select jsonb_object_agg(estate,balance) from fauxlore.state_treasuries where state_id=state_key),'{}'::jsonb),
      'groups',coalesce((select jsonb_agg(jsonb_build_object('layer',l.layer,'id',c.id,'name',c.name,
        'base_rate',(cfg#>>array[case l.layer when 'races' then 'raceTaxRates' else 'religionTaxRates' end,c.name])::numeric,
        'rate',coalesce(r.rate,(cfg#>>array[case l.layer when 'races' then 'raceTaxRates' else 'religionTaxRates' end,c.name])::numeric),
        'changed_this_turn',coalesce(r.changed_year=calendar_row.year and r.changed_turn=calendar_row.turn,false)) order by l.layer,c.name)
        from (values('races'::text),('religions'::text)) l(layer) join fauxlore.map_categories c on c.layer=l.layer
        left join fauxlore.state_tax_rates r on r.state_id=state_key and r.layer=l.layer and r.category_id=c.id),'[]'::jsonb));
  end if;
  if method not in ('POST','PATCH') or request_id is null or jsonb_typeof(body) is distinct from 'object' or body-array['layer','category_id','rate']<>'{}' or
    jsonb_typeof(body->'layer') is distinct from 'string' or jsonb_typeof(body->'category_id') is distinct from 'number' or jsonb_typeof(body->'rate') is distinct from 'number' then
    raise sqlstate '22023' using message='Некорректное изменение базовой ставки'; end if;
  layer_key:=body->>'layer'; category_key:=(body->>'category_id')::integer; rate_value:=(body->>'rate')::numeric;
  if layer_key not in ('races','religions') or rate_value<0 or rate_value>100 then raise sqlstate '22023' using message='Ставка должна быть от 0 до 100 G'; end if;
  select name into category_name from fauxlore.map_categories where layer=layer_key and id=category_key;
  if category_name is null or not ((cfg->(case layer_key when 'races' then 'raceTaxRates' else 'religionTaxRates' end)) ? category_name) then
    raise sqlstate '22023' using message='Для выбранной группы не задана базовая ставка'; end if;
  perform pg_advisory_xact_lock(hashtextextended(a.id::text||':'||request_id::text,0));
  select * into prior from fauxlore.operations o where o.account_id=a.id and o.request_id=state_tax_rates_api.request_id;
  fp:=md5(jsonb_build_array(method,path,body)::text);
  if found then if prior.fingerprint<>fp then raise sqlstate '22023' using message='Идентификатор команды уже использован'; end if; return prior.result; end if;
  select * into calendar_row from fauxlore.game_calendar where singleton=true for share;
  select * into existing from fauxlore.state_tax_rates where state_id=state_key and layer=layer_key and category_id=category_key for update;
  if found and existing.changed_year=calendar_row.year and existing.changed_turn=calendar_row.turn then
    raise sqlstate '22023' using message='Эту ставку уже меняли в текущем ходу'; end if;
  if not is_admin then
    update fauxlore.state_profiles set prestige=prestige-3 where state_id=state_key and prestige>=3;
    if not found then raise sqlstate '22023' using message='Недостаточно ОП: изменение ставки стоит 3 ОП'; end if;
  end if;
  insert into fauxlore.state_tax_rates(state_id,layer,category_id,rate,changed_year,changed_turn,changed_by)
    values(state_key,layer_key,category_key,rate_value,calendar_row.year,calendar_row.turn,a.id)
    on conflict(state_id,layer,category_id) do update set rate=excluded.rate,changed_year=excluded.changed_year,changed_turn=excluded.changed_turn,changed_by=excluded.changed_by,updated_at=now();
  result:=jsonb_build_object('state_id',state_key,'state_name',state_name,'layer',layer_key,'category_id',category_key,'category_name',category_name,
    'rate',rate_value,'cost',case when is_admin then 0 else 3 end,'prestige',(select prestige from fauxlore.state_profiles where state_id=state_key));
  insert into fauxlore.operations(account_id,request_id,fingerprint,result) values(a.id,state_tax_rates_api.request_id,fp,result);
  return result;
end $$;
revoke all on function fauxlore.state_tax_rates_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.state_tax_rates_api(text,text,jsonb,uuid) to authenticated;

create or replace function fauxlore.test_turn_api(path text,method text,body jsonb,request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a fauxlore.accounts; cal fauxlore.game_calendar; snap fauxlore.turn_test_snapshot; payload jsonb; result jsonb; revision bigint; t text; snap_row jsonb;
begin
  a:=fauxlore.current_account(); if a.role is distinct from 'admin' then raise sqlstate '42501' using message='Нужна роль администратора'; end if;
  if path='admin/turn/test' and method='GET' then
    select * into snap from fauxlore.turn_test_snapshot where singleton=true;
    if not found then return jsonb_build_object('active',false); end if;
    return jsonb_build_object('active',snap.after_revision is not null,'before_year',snap.before_year,'before_turn',snap.before_turn,
      'after_year',snap.after_year,'after_turn',snap.after_turn,'created_at',snap.created_at);
  end if;
  if path='admin/turn/test/advance' and method='POST' then
    if request_id is null then raise sqlstate '22023' using message='Нужен идентификатор команды'; end if;
    if exists(select 1 from fauxlore.turn_test_snapshot where singleton=true) then raise sqlstate '22023' using message='Сначала откатите или завершите предыдущий тестовый ход'; end if;
    select * into cal from fauxlore.game_calendar where singleton=true for update;
    if (body->>'expected_year')::integer<>cal.year or (body->>'expected_turn')::integer<>cal.turn then raise sqlstate '40001' using message='Ход уже изменён. Обновите страницу.'; end if;
    select coalesce((value_json#>>'{}')::bigint,0) into revision from fauxlore._settings where key='live_revision';
    select jsonb_build_object(
      'state_profiles',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.state_profiles x),
      'state_group_politics',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.state_group_politics x),
      'state_characters',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.state_characters x),
      'state_succession_events',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.state_succession_events x),
      'state_birth_events',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.state_birth_events x),
      'notifications',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.notifications x),
      'state_treasuries',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.state_treasuries x),
      'state_treasury_debts',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.state_treasury_debts x),
      'state_budget_ledger',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.state_budget_ledger x),
      'turn_economy_reports',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.turn_economy_reports x),
      'game_calendar',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from fauxlore.game_calendar x)
    ) into payload;
    insert into fauxlore.turn_test_snapshot(singleton,payload,before_year,before_turn,actor_id,advance_request_id)
      values(true,payload,cal.year,cal.turn,a.id,request_id);
    result:=fauxlore.turn_api('admin/turn/advance','POST',body,request_id);
    select * into cal from fauxlore.game_calendar where singleton=true;
    select coalesce((value_json#>>'{}')::bigint,0) into revision from fauxlore._settings where key='live_revision';
    update fauxlore.turn_test_snapshot set after_year=cal.year,after_turn=cal.turn,after_revision=revision where singleton=true;
    return result||jsonb_build_object('test_mode',true,'rollback_available',true);
  end if;
  if path='admin/turn/test/rollback' and method='POST' then
    select * into snap from fauxlore.turn_test_snapshot where singleton=true for update;
    if not found or snap.after_revision is null then raise sqlstate '22023' using message='Нет завершённого тестового хода для отката'; end if;
    lock table fauxlore.state_profiles,fauxlore.state_group_politics,fauxlore.state_characters,fauxlore.state_succession_events,
      fauxlore.state_birth_events,fauxlore.notifications,fauxlore.state_treasuries,fauxlore.state_treasury_debts,
      fauxlore.state_budget_ledger,fauxlore.turn_economy_reports,fauxlore.game_calendar in access exclusive mode;
    if (select coalesce((value_json#>>'{}')::bigint,0) from fauxlore._settings where key='live_revision')<>snap.after_revision then
      raise sqlstate '40001' using message='После тестового хода появились новые изменения. Откат отменён, чтобы их не затереть.'; end if;
    if not exists(select 1 from fauxlore.game_calendar where singleton and year=snap.after_year and turn=snap.after_turn) then
      raise sqlstate '40001' using message='Игровой календарь изменён после теста. Откат отменён.'; end if;
    perform set_config('session_replication_role','replica',true);
    delete from fauxlore.notifications; delete from fauxlore.state_birth_events; delete from fauxlore.state_budget_ledger;
    delete from fauxlore.turn_economy_reports; delete from fauxlore.state_succession_events; delete from fauxlore.state_group_politics;
    delete from fauxlore.state_characters; delete from fauxlore.state_treasuries; delete from fauxlore.state_treasury_debts;
    for t in select unnest(array['state_profiles','state_group_politics','state_characters','state_succession_events','state_birth_events','notifications','state_treasuries','state_treasury_debts','state_budget_ledger','turn_economy_reports','game_calendar']) loop
      snap_row:=snap.payload->t;
      if t='state_profiles' or t='game_calendar' then
        execute format('update fauxlore.%1$I target set %2$s from jsonb_populate_recordset(null::fauxlore.%1$I,$1) saved where target.%3$I=saved.%3$I',
          t,(select string_agg(format('%1$I=saved.%1$I',column_name),',' order by ordinal_position) from information_schema.columns where table_schema='fauxlore' and table_name=t and column_name<>case t when 'state_profiles' then 'state_id' else 'singleton' end),
          case t when 'state_profiles' then 'state_id' else 'singleton' end) using snap_row;
      else
        execute format('insert into fauxlore.%I select * from jsonb_populate_recordset(null::fauxlore.%I,$1)',t,t) using snap_row;
      end if;
    end loop;
    delete from fauxlore.operations where account_id=snap.actor_id and request_id=snap.advance_request_id;
    perform set_config('session_replication_role','origin',true);
    update fauxlore._settings set value_json=to_jsonb(coalesce((value_json#>>'{}')::bigint,0)+1) where key='live_revision';
    delete from fauxlore.turn_test_snapshot where singleton=true;
    return jsonb_build_object('rolled_back',true,'year',snap.before_year,'turn',snap.before_turn);
  end if;
  raise sqlstate 'P0002' using message='Метод API не найден';
end $$;
revoke all on function fauxlore.test_turn_api(text,text,jsonb,uuid) from public,anon,authenticated;
grant execute on function fauxlore.test_turn_api(text,text,jsonb,uuid) to authenticated;

-- Include state-specific rates in the public map payload so province calculations use the active state's values.
do $$
declare fn text; old_fragment text; new_fragment text;
begin
  fn:=replace(pg_get_functiondef('fauxlore.map_payload()'::regprocedure),chr(13),'');
  old_fragment:='case when v.layer=''states'' then jsonb_build_object(''crime'',coalesce((select sp.crime from fauxlore.state_profiles sp where sp.state_id=c.id),0.2)) else ''{}''::jsonb end';
  new_fragment:='case when v.layer=''states'' then jsonb_build_object(''crime'',coalesce((select sp.crime from fauxlore.state_profiles sp where sp.state_id=c.id),0.2),''race_tax_rates'',coalesce((select jsonb_object_agg(mc.name,r.rate) from fauxlore.state_tax_rates r join fauxlore.map_categories mc on mc.layer=r.layer and mc.id=r.category_id where r.state_id=c.id and r.layer=''races''),''{}''::jsonb),''religion_tax_rates'',coalesce((select jsonb_object_agg(mc.name,r.rate) from fauxlore.state_tax_rates r join fauxlore.map_categories mc on mc.layer=r.layer and mc.id=r.category_id where r.state_id=c.id and r.layer=''religions''),''{}''::jsonb)) else ''{}''::jsonb end';
  if position('race_tax_rates' in fn)>0 then return; end if;
  if position(old_fragment in fn)=0 then raise exception 'Could not locate state layer JSON in map_payload'; end if;
  execute replace(fn,old_fragment,new_fragment);
end $$;

create or replace function public.fauxlore_api(path text,method text default 'GET',body jsonb default '{}',request_id uuid default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
begin
  if path in ('my/economy/treasuries','admin/economy/treasuries') or path ~ '^(my|admin)/states/[0-9]+/tax-rates$' then
    return fauxlore.state_tax_rates_api(path,method,body,request_id);
  elsif path='admin/turn/test' or path like 'admin/turn/test/%' then
    return fauxlore.test_turn_api(path,method,body,request_id);
  elsif path='map/revision' and method='GET' then return fauxlore.map_revision();
  elsif path ~ '^my/states/[0-9]+/(birth-events|birth-events/[0-9]+/name|marriage-candidates|marriages/local)$' then return fauxlore.character_lifecycle_api(path,method,body,request_id);
  elsif path ~ '^my/states/[0-9]+/characters$' or path ~ '^admin/states/[0-9]+/characters$' then return fauxlore.characters_api(path,method,body,request_id);
  elsif path='my/marriage-offers' or path ~ '^(my|admin)/marriage-offers/[0-9]+/(accept|reject)$' then return fauxlore.dynastic_marriage_api(path,method,body,request_id);
  elsif path ~ '^(my|admin)/states/[0-9]+/abdicate$' then return fauxlore.abdicate_api(path,method,body,request_id);
  elsif path ~ '^(my|admin)/states/[0-9]+/(succession(/events/[0-9]+/choose)?|politics|designate)$' then return fauxlore.succession_api(path,method,body,request_id);
  elsif path='my/applications' and method='GET' then return fauxlore.my_applications();
  elsif path='my/applications' and method='POST' then return fauxlore.registration_api_with_surname(path,method,body,request_id);
  elsif path ~ '^admin/applications/[0-9]+$' and method='PATCH' then return fauxlore.registration_api_with_surname(path,method,body,request_id);
  elsif path='my/applications' or path like 'admin/applications%' or path='notifications' or path like 'notifications/%' then return fauxlore.registration_api(path,method,body,request_id);
  elsif path ~ '^my/applications/[0-9]+$' then return fauxlore.application_details(path,method,body);
  elsif path ~ '^state-emblem/[0-9]+$' or path ~ '^admin/state-emblem/[0-9]+$' then return fauxlore.state_emblem_api(path,method,body,request_id);
  elsif path ~ '^admin/states/[0-9]+/army$' then return fauxlore.army_budget_api(path,method,body,request_id);
  elsif path='admin/turn/latest-report' then return fauxlore.turn_budget_report_api(path,method);
  elsif path='game/calendar' or path='admin/turn/advance' then return fauxlore.turn_api(path,method,body,request_id);
  elsif path='admin/states' then return fauxlore.state_api(path,method,body,request_id);
  elsif path='my/states' or path like 'admin/states/%' then return fauxlore.game_state_api(path,method,body,request_id);
  else return fauxlore.api(path,method,body,request_id); end if;
end $$;
revoke all on function public.fauxlore_api(text,text,jsonb,uuid) from public;
grant execute on function public.fauxlore_api(text,text,jsonb,uuid) to anon,authenticated;
notify pgrst,'reload schema';

